import { useState } from 'react'
import { ArrowLeft, Settings, Mail, Plus, Upload, Download, GripVertical, ChevronDown, ChevronUp } from 'lucide-react'
import type { Account } from '../types'

interface Props {
  accounts: Account[]
  onBack: () => void
  onAddAccount: () => void
}

export default function SettingsPage({ accounts, onBack, onAddAccount }: Props) {
  const [generalOpen, setGeneralOpen] = useState(false)
  const [fontSize, setFontSize] = useState<'small' | 'medium' | 'large'>('medium')
  const [language, setLanguage] = useState<'zh' | 'en'>('zh')
  const [theme, setTheme] = useState<'light' | 'dark'>('light')

  return (
    <div className="flex flex-col h-full bg-gray-100">
      <div className="flex items-center gap-3 px-4 py-3 bg-gray-100 border-b border-gray-200">
        <button onClick={onBack}><ArrowLeft size={22} className="text-gray-600" /></button>
        <h1 className="text-lg font-semibold text-gray-900">设置</h1>
      </div>

      <div className="flex-1 overflow-y-auto">
        {/* General */}
        <div className="bg-white mt-2">
          <button
            className="w-full flex items-center gap-3 px-4 py-4 hover:bg-gray-50"
            onClick={() => setGeneralOpen(o => !o)}
          >
            <Settings size={20} className="text-gray-500" />
            <span className="flex-1 text-left text-gray-800">常规设置</span>
            {generalOpen ? <ChevronUp size={18} className="text-gray-400" /> : <ChevronDown size={18} className="text-gray-400" />}
          </button>

          {generalOpen && (
            <div className="border-t border-gray-100 px-4 py-3 space-y-4">
              {/* Font size */}
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-700">字体大小</span>
                <div className="flex gap-1">
                  {(['small', 'medium', 'large'] as const).map(s => (
                    <button
                      key={s}
                      onClick={() => setFontSize(s)}
                      className={`px-3 py-1 rounded text-xs border ${fontSize === s ? 'bg-blue-500 text-white border-blue-500' : 'text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                    >
                      {s === 'small' ? '小' : s === 'medium' ? '中' : '大'}
                    </button>
                  ))}
                </div>
              </div>

              {/* Language */}
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-700">语言</span>
                <div className="flex gap-1">
                  {(['zh', 'en'] as const).map(l => (
                    <button
                      key={l}
                      onClick={() => setLanguage(l)}
                      className={`px-3 py-1 rounded text-xs border ${language === l ? 'bg-blue-500 text-white border-blue-500' : 'text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                    >
                      {l === 'zh' ? '中文' : 'English'}
                    </button>
                  ))}
                </div>
              </div>

              {/* Theme */}
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-700">主题</span>
                <div className="flex gap-1">
                  {(['light', 'dark'] as const).map(t => (
                    <button
                      key={t}
                      onClick={() => setTheme(t)}
                      className={`px-3 py-1 rounded text-xs border ${theme === t ? 'bg-blue-500 text-white border-blue-500' : 'text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                    >
                      {t === 'light' ? '浅色' : '深色'}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Accounts section */}
        <div className="mt-4">
          <div className="px-4 py-2 text-sm font-semibold text-blue-500">账号</div>
          <div className="bg-white">
            {accounts.map(acc => (
              <div key={acc.id} className="flex items-center gap-3 px-4 py-4 border-b border-gray-50">
                <Mail size={20} className="text-gray-400" />
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium text-gray-800 truncate">{acc.email}</div>
                  <div className="text-xs text-gray-400 truncate">{acc.email}</div>
                </div>
                <GripVertical size={18} className="text-gray-300" />
              </div>
            ))}
            <button
              onClick={onAddAccount}
              className="w-full flex items-center gap-3 px-4 py-4 hover:bg-gray-50"
            >
              <Plus size={20} className="text-gray-400" />
              <span className="text-gray-700">添加账号</span>
            </button>
          </div>
        </div>

        {/* Backup */}
        <div className="mt-4 mb-6">
          <div className="px-4 py-2 text-sm font-semibold text-blue-500">备份</div>
          <div className="bg-white">
            <button className="w-full flex items-center gap-3 px-4 py-4 border-b border-gray-50 hover:bg-gray-50">
              <Upload size={20} className="text-gray-400" />
              <span className="text-gray-700">导出设置</span>
            </button>
            <button className="w-full flex items-center gap-3 px-4 py-4 hover:bg-gray-50">
              <Download size={20} className="text-gray-400" />
              <span className="text-gray-700">导入设置</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

