import { createContext, useContext, useEffect, useState } from 'react'

type Theme = 'light' | 'dark'
type Language = 'zh' | 'en'
type FontSize = 'small' | 'medium' | 'large'

interface Settings {
  theme: Theme
  language: Language
  fontSize: FontSize
  setTheme: (v: Theme) => void
  setLanguage: (v: Language) => void
  setFontSize: (v: FontSize) => void
}

const SettingsContext = createContext<Settings>(null!)

const fontSizeMap: Record<FontSize, string> = { small: '14px', medium: '16px', large: '18px' }

export function SettingsProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<Theme>(() => (localStorage.getItem('theme') as Theme) || 'light')
  const [language, setLanguageState] = useState<Language>(() => (localStorage.getItem('language') as Language) || 'zh')
  const [fontSize, setFontSizeState] = useState<FontSize>(() => (localStorage.getItem('fontSize') as FontSize) || 'medium')

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark')
    localStorage.setItem('theme', theme)
  }, [theme])

  useEffect(() => {
    document.documentElement.style.fontSize = fontSizeMap[fontSize]
    localStorage.setItem('fontSize', fontSize)
  }, [fontSize])

  useEffect(() => {
    localStorage.setItem('language', language)
  }, [language])

  const setTheme = (v: Theme) => setThemeState(v)
  const setLanguage = (v: Language) => setLanguageState(v)
  const setFontSize = (v: FontSize) => setFontSizeState(v)

  return (
    <SettingsContext.Provider value={{ theme, language, fontSize, setTheme, setLanguage, setFontSize }}>
      {children}
    </SettingsContext.Provider>
  )
}

export const useSettings = () => useContext(SettingsContext)

