import { useState } from 'react'
import { Menu, Search, SlidersHorizontal, MoreVertical, Edit } from 'lucide-react'
import type { Account, Email, AccountType } from './types'
import { MOCK_ACCOUNTS, MOCK_EMAILS, getAccountById, getInitials } from './data'
import EmailItem from './components/EmailItem'
import EmailDetail from './components/EmailDetail'
import Drawer from './components/Drawer'
import AddAccountModal from './components/AddAccountModal'
import SettingsPage from './components/SettingsPage'

type View = 'inbox' | 'detail' | 'settings'

const ACCOUNT_COLORS = ['#4A90D9','#E91E8C','#FF7043','#8BC34A','#9C27B0','#26A69A','#FF9800','#607D8B']

export default function App() {
  const [accounts, setAccounts] = useState<Account[]>(MOCK_ACCOUNTS)
  const [emails, setEmails] = useState<Email[]>(MOCK_EMAILS)
  const [selectedAccountId, setSelectedAccountId] = useState<string | null>(null)
  const [selectedEmail, setSelectedEmail] = useState<Email | null>(null)
  const [view, setView] = useState<View>('inbox')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [showAddAccount, setShowAddAccount] = useState(false)

  const visibleEmails = selectedAccountId
    ? emails.filter(e => e.accountId === selectedAccountId && e.folder === 'inbox')
    : emails.filter(e => e.folder === 'inbox')

  const selectedAccount = selectedAccountId ? getAccountById(accounts, selectedAccountId) : null

  const title = selectedAccount ? selectedAccount.email : (selectedAccountId === null ? '统一收件箱' : '收件箱')

  function handleOpenEmail(email: Email) {
    setSelectedEmail(email)
    setEmails(prev => prev.map(e => e.id === email.id ? { ...e, read: true } : e))
    setView('detail')
  }

  function handleStar(emailId: string) {
    setEmails(prev => prev.map(e => e.id === emailId ? { ...e, starred: !e.starred } : e))
  }

  function handleDelete(emailId: string) {
    setEmails(prev => prev.map(e => e.id === emailId ? { ...e, folder: 'trash' } : e))
    setView('inbox')
  }

  function handleAddAccount(email: string, type: AccountType, _credential: string) {
    const newAcc: Account = {
      id: Date.now().toString(),
      email,
      type,
      color: ACCOUNT_COLORS[accounts.length % ACCOUNT_COLORS.length],
      unread: 0,
    }
    setAccounts(prev => [...prev, newAcc])
  }

  if (view === 'settings') {
    return (
      <div className="min-h-screen bg-gray-100 flex justify-center">
        <div className="w-full max-w-2xl flex flex-col" style={{ minHeight: '100dvh' }}>
          <SettingsPage
            accounts={accounts}
            onBack={() => setView('inbox')}
            onAddAccount={() => { setView('inbox'); setShowAddAccount(true) }}
          />
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-white flex justify-center">
      <div className="w-full max-w-2xl flex flex-col relative" style={{ minHeight: '100dvh' }}>

        {/* Drawer overlay */}
        {drawerOpen && (
          <div className="absolute inset-0 z-40 flex">
            <div className="w-4/5 max-w-xs h-full shadow-xl">
              <Drawer
                accounts={accounts}
                selectedAccountId={selectedAccountId}
                onSelectAccount={setSelectedAccountId}
                onAddAccount={() => { setDrawerOpen(false); setShowAddAccount(true) }}
                onSettings={() => { setDrawerOpen(false); setView('settings') }}
                onSync={() => setDrawerOpen(false)}
                onClose={() => setDrawerOpen(false)}
              />
            </div>
            <div className="flex-1 bg-black/30" onClick={() => setDrawerOpen(false)} />
          </div>
        )}

        {/* Email detail */}
        {view === 'detail' && selectedEmail ? (
          <EmailDetail
            email={selectedEmail}
            account={getAccountById(accounts, selectedEmail.accountId)}
            onBack={() => setView('inbox')}
            onDelete={() => handleDelete(selectedEmail.id)}
            onStar={() => handleStar(selectedEmail.id)}
          />
        ) : (
          <>
            {/* Top bar */}
            <div className="flex items-center justify-between px-4 py-3 bg-white border-b border-gray-100 sticky top-0 z-10">
              <div className="flex items-center gap-3">
                <button onClick={() => setDrawerOpen(true)}>
                  <Menu size={22} className="text-gray-700" />
                </button>
                <h1 className="text-lg font-semibold text-gray-900 truncate max-w-[180px]">{title}</h1>
              </div>
              <div className="flex items-center gap-3">
                <button><Search size={22} className="text-gray-600" /></button>
                <button><SlidersHorizontal size={20} className="text-gray-600" /></button>
                <button><MoreVertical size={20} className="text-gray-600" /></button>
              </div>
            </div>

            {/* Email list */}
            <div className="flex-1 overflow-y-auto">
              {visibleEmails.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-gray-400">
                  <div className="text-4xl mb-3">📭</div>
                  <div>暂无邮件</div>
                </div>
              ) : (
                visibleEmails.map(email => (
                  <EmailItem
                    key={email.id}
                    email={email}
                    account={getAccountById(accounts, email.accountId)}
                    onClick={() => handleOpenEmail(email)}
                    onStar={() => handleStar(email.id)}
                  />
                ))
              )}
            </div>

            {/* Compose FAB */}
            <button className="absolute bottom-6 right-4 w-14 h-14 bg-blue-600 rounded-full flex items-center justify-center shadow-lg">
              <Edit size={22} className="text-white" />
            </button>
          </>
        )}

        {/* Add account modal */}
        {showAddAccount && (
          <AddAccountModal
            onClose={() => setShowAddAccount(false)}
            onAdd={handleAddAccount}
          />
        )}
      </div>
    </div>
  )
}

import { RefreshCw, Plus, Settings, ChevronUp, Users } from 'lucide-react'
import type { Account } from '../types'
import { getInitials } from '../data'
import Avatar from './Avatar'

interface Props {
  accounts: Account[]
  selectedAccountId: string | null
  onSelectAccount: (id: string | null) => void
  onAddAccount: () => void
  onSettings: () => void
  onSync: () => void
  onClose: () => void
}

export default function Drawer({ accounts, selectedAccountId, onSelectAccount, onAddAccount, onSettings, onSync, onClose }: Props) {
  const totalUnread = accounts.reduce((s, a) => s + a.unread, 0)

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Account list header */}
      <div className="flex items-center justify-between px-4 py-4 border-b border-gray-100">
        <span className="font-semibold text-gray-800">账号列表</span>
        <button onClick={onClose}><ChevronUp size={20} className="text-gray-500" /></button>
      </div>

      <div className="flex-1 overflow-y-auto">
        {/* Unified account */}
        <button
          onClick={() => { onSelectAccount(null); onClose() }}
