  onSelectAccount: (id: string | null) => void
  onAddAccount: () => void
  onSettings: () => void
  onSync: () => void
  onClose: () => void
}

export default function Drawer({ accounts, selectedAccountId, onSelectAccount, onAddAccount, onSettings, onSync, onClose }: Props) {
  const totalUnread = accounts.reduce((s, a) => s + a.unread, 0)

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Account list header */}
      <div className="flex items-center justify-between px-4 py-4 border-b border-gray-100">
        <span className="font-semibold text-gray-800">账号列表</span>
        <button onClick={onClose}><ChevronUp size={20} className="text-gray-500" /></button>
      </div>

      <div className="flex-1 overflow-y-auto">
        {/* Unified account */}
        <button
          onClick={() => { onSelectAccount(null); onClose() }}
          className={`w-full flex items-center gap-3 px-4 py-3 mx-2 my-2 rounded-full transition-colors ${selectedAccountId === null ? 'bg-blue-600 text-white' : 'hover:bg-gray-100'}`}
        >
          <div className={`w-11 h-11 rounded-full flex items-center justify-center ${selectedAccountId === null ? 'bg-blue-500' : 'bg-gray-300'}`}>
            <Users size={22} className="text-white" />
          </div>
          <span className={`flex-1 text-left font-semibold ${selectedAccountId === null ? 'text-white' : 'text-gray-800'}`}>
            统一账号
          </span>
          {totalUnread > 0 && (
            <span className={`text-sm font-bold ${selectedAccountId === null ? 'text-white' : 'text-gray-600'}`}>
              {totalUnread}
            </span>
          )}
        </button>

        {/* Individual accounts */}
        {accounts.map(acc => (
          <button
            key={acc.id}
            onClick={() => { onSelectAccount(acc.id); onClose() }}
            className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 transition-colors ${selectedAccountId === acc.id ? 'bg-blue-50' : ''}`}
          >
            <Avatar text={getInitials(acc.email)} color={acc.color} />
            <span className="flex-1 text-left text-sm text-gray-700 truncate">{acc.email}</span>
            {acc.unread > 0 && (
              <span className="text-sm text-gray-500 font-medium">{acc.unread}</span>
            )}
          </button>
        ))}
      </div>

      {/* Bottom actions */}
      <div className="border-t border-gray-100 pb-4">
        <button onClick={onSync} className="w-full flex items-center gap-3 px-6 py-3 hover:bg-gray-50 text-gray-700">
          <RefreshCw size={20} /> <span>同步全部账号</span>
        </button>
        <button onClick={onAddAccount} className="w-full flex items-center gap-3 px-6 py-3 hover:bg-gray-50 text-gray-700">
          <Plus size={20} /> <span>添加账号</span>
        </button>
        <button onClick={onSettings} className="w-full flex items-center gap-3 px-6 py-3 hover:bg-gray-50 text-gray-700">
          <Settings size={20} /> <span>设置</span>
        </button>
      </div>
    </div>
  )
}

