router.post('/', (req, res) => {
  const { email, type, credential } = req.body
  if (!email || !type || !credential) return res.status(400).json({ error: 'missing fields' })

  const count = db.prepare('SELECT COUNT(*) as n FROM accounts').get().n
  const id = randomUUID()
  const color = COLORS[count % COLORS.length]

  // config stores credential (in production: encrypt this)
  const config = JSON.stringify({ credential })

  db.prepare('INSERT INTO accounts (id, email, type, color, config) VALUES (?, ?, ?, ?, ?)')
    .run(id, email, type, color, config)

  res.status(201).json({ id, email, type, color })
})

