const { ConfidentialClientApplication } = require('@azure/msal-node')
const db = require('../db')

const SCOPES = ['https://graph.microsoft.com/Mail.Read', 'https://graph.microsoft.com/Mail.ReadWrite', 'offline_access']

function getMsalClient() {
  return new ConfidentialClientApplication({
    auth: {
      clientId: process.env.OUTLOOK_CLIENT_ID,
      clientSecret: process.env.OUTLOOK_CLIENT_SECRET,
      authority: 'https://login.microsoftonline.com/common',
    },
  })
}

async function getAuthUrl(redirectUri) {
  const client = getMsalClient()
  return client.getAuthCodeUrl({ scopes: SCOPES, redirectUri })
}

async function handleCallback(code, redirectUri) {
  const client = getMsalClient()
  const result = await client.acquireTokenByCode({ code, scopes: SCOPES, redirectUri })
  return result
}

async function getAccessToken(accountId) {
  const row = db.prepare('SELECT config FROM accounts WHERE id = ?').get(accountId)
  if (!row) throw new Error('account not found')
  const config = JSON.parse(row.config)

  const client = getMsalClient()
  const result = await client.acquireTokenByRefreshToken({
    refreshToken: config.refreshToken,
    scopes: SCOPES,
  })
  return result.accessToken
}

module.exports = { getAuthUrl, handleCallback, getAccessToken }

