          >
            <Avatar text={getInitials(acc.email)} color={acc.color} />
            <span className="flex-1 text-left text-sm text-gray-700 truncate">{acc.email}</span>
            {acc.unread > 0 && (
              <span className="text-sm text-gray-500 font-medium">{acc.unread}</span>
            )}
          </button>
        ))}
