  )
}

import { X } from 'lucide-react'
import { useState } from 'react'
import type { AccountType } from '../types'

interface Props {
  onClose: () => void
  onAdd: (email: string, type: AccountType, credential: string) => void
}

const PROVIDERS = [
  { type: 'gmail' as AccountType, label: 'Gmail', hint: '16位应用专用密码', placeholder: 'xxxx xxxx xxxx xxxx', inputType: 'password' },
  { type: 'outlook' as AccountType, label: 'Outlook / Hotmail / Live', hint: 'OAuth2 授权登录', placeholder: '', inputType: 'oauth' },
  { type: 'qq' as AccountType, label: 'QQ 邮箱', hint: 'QQ 邮箱授权码', placeholder: '16位授权码', inputType: 'password' },
]

export default function AddAccountModal({ onClose, onAdd }: Props) {
  const [step, setStep] = useState<'pick' | 'form'>('pick')
  const [provider, setProvider] = useState<typeof PROVIDERS[0] | null>(null)
  const [email, setEmail] = useState('')
  const [credential, setCredential] = useState('')

  function handlePick(p: typeof PROVIDERS[0]) {
    setProvider(p)
    setStep('form')
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (!provider) return
    onAdd(email, provider.type, credential)
    onClose()
  }

  return (
    <div className="fixed inset-0 bg-black/40 z-50 flex items-end sm:items-center justify-center">
      <div className="bg-white w-full sm:max-w-md rounded-t-2xl sm:rounded-2xl p-6">
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-lg font-semibold">
            {step === 'pick' ? '选择邮箱类型' : `添加 ${provider?.label}`}
          </h2>
          <button onClick={onClose}><X size={22} className="text-gray-500" /></button>
        </div>

        {step === 'pick' && (
          <div className="flex flex-col gap-3">
            {PROVIDERS.map(p => (
              <button
                key={p.type}
                onClick={() => handlePick(p)}
                className="flex items-center gap-3 p-4 border border-gray-200 rounded-xl hover:bg-gray-50 text-left"
              >
                <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center font-bold text-blue-600 text-sm">
                  {p.label[0]}
                </div>
                <div>
                  <div className="font-medium text-gray-800">{p.label}</div>
                  <div className="text-xs text-gray-500">{p.hint}</div>
                </div>
              </button>
            ))}
          </div>
        )}

        {step === 'form' && provider && (
          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div>
              <label className="text-sm text-gray-600 mb-1 block">邮箱地址</label>
              <input
                type="email"
                required
                value={email}
                onChange={e => setEmail(e.target.value)}
                placeholder={`your@${provider.type === 'qq' ? 'qq.com' : provider.type === 'gmail' ? 'gmail.com' : 'outlook.com'}`}
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-blue-500"
              />
            </div>

            {provider.inputType === 'oauth' ? (
              <button
                type="button"
                className="w-full py-3 bg-blue-600 text-white rounded-xl font-medium"
                onClick={() => { onAdd(email, provider.type, 'oauth'); onClose() }}
              >
                使用 Microsoft 授权登录
              </button>
            ) : (
              <>
                <div>
                  <label className="text-sm text-gray-600 mb-1 block">{provider.hint}</label>
                  <input
                    type="password"
                    required
                    value={credential}
                    onChange={e => setCredential(e.target.value)}
                    placeholder={provider.placeholder}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-blue-500"
                  />
                </div>
                <button type="submit" className="w-full py-3 bg-blue-600 text-white rounded-xl font-medium">
                  添加账号
                </button>
              </>
            )}

            <button type="button" onClick={() => setStep('pick')} className="text-sm text-gray-500 text-center">
              返回
            </button>
          </form>
        )}
      </div>
    </div>
  )
}

