import { useState, useEffect, useCallback } from 'react'
import { Menu, Edit } from 'lucide-react'
import type { Account, Email, AccountType } from './types'
import EmailItem from './components/EmailItem'
import EmailDetail from './components/EmailDetail'
import Drawer from './components/Drawer'
import AddAccountModal from './components/AddAccountModal'
import SettingsPage from './components/SettingsPage'

type View = 'inbox' | 'detail' | 'settings'

// Map backend row → frontend Email
function mapEmail(r: any): Email {
  return {
    id: r.id,
    accountId: r.account_id,
    from: r.from_addr,
    fromName: r.from_name,
    to: '',
    subject: r.subject,
    preview: r.preview,
    body: r.body ?? '',
    date: r.date,
    read: r.read === 1,
    starred: r.starred === 1,
    folder: r.folder,
  }
}

function getAccountById(accounts: Account[], id: string) {
  return accounts.find(a => a.id === id)
}

export default function App() {
  const [accounts, setAccounts] = useState<Account[]>([])
  const [emails, setEmails] = useState<Email[]>([])
  const [selectedAccountId, setSelectedAccountId] = useState<string | null>(null)
  const [selectedEmail, setSelectedEmail] = useState<Email | null>(null)
  const [view, setView] = useState<View>('inbox')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [showAddAccount, setShowAddAccount] = useState(false)
  const [loading, setLoading] = useState(true)

  const fetchAccounts = useCallback(async () => {
    const res = await fetch('/api/accounts')
    const data = await res.json()
    setAccounts(data)
    return data as Account[]
  }, [])

  const fetchEmails = useCallback(async (accountId?: string | null) => {
    const url = accountId ? `/api/emails?accountId=${accountId}` : '/api/emails'
    const res = await fetch(url)
    const data = await res.json()
    setEmails(data.map(mapEmail))
  }, [])

  useEffect(() => {
    setLoading(true)
    Promise.all([fetchAccounts(), fetchEmails(null)]).finally(() => setLoading(false))
  }, [])

  useEffect(() => {
    fetchEmails(selectedAccountId)
  }, [selectedAccountId])

  const visibleEmails = emails.filter(e => e.folder === 'inbox')
  const selectedAccount = selectedAccountId ? getAccountById(accounts, selectedAccountId) : null
  const title = selectedAccount ? selectedAccount.email : '统一收件箱'

  async function handleOpenEmail(email: Email) {
    setSelectedEmail(email)
    setView('detail')
    if (!email.read) {
      await fetch(`/api/emails/${email.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ read: true }) })
      setEmails(prev => prev.map(e => e.id === email.id ? { ...e, read: true } : e))
    }
  }

  async function handleStar(emailId: string) {
    const email = emails.find(e => e.id === emailId)
    if (!email) return
    const starred = !email.starred
    await fetch(`/api/emails/${emailId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ starred }) })
    setEmails(prev => prev.map(e => e.id === emailId ? { ...e, starred } : e))
    if (selectedEmail?.id === emailId) setSelectedEmail(e => e ? { ...e, starred } : e)
  }

  async function handleDelete(emailId: string) {
    await fetch(`/api/emails/${emailId}`, { method: 'DELETE' })
    setEmails(prev => prev.filter(e => e.id !== emailId))
    setView('inbox')
  }

  async function handleAddAccount(email: string, type: AccountType, credential: string) {
    const res = await fetch('/api/accounts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, type, credential }),
    })
    if (res.ok) await fetchAccounts()
  }

  async function handleDeleteAccount(id: string) {
    await fetch(`/api/accounts/${id}`, { method: 'DELETE' })
    await fetchAccounts()
    if (selectedAccountId === id) setSelectedAccountId(null)
  }

  async function handleSync(accountId?: string) {
    const ids = accountId ? [accountId] : accounts.map(a => a.id)
    await Promise.all(ids.map(id => fetch(`/api/emails/sync/${id}`, { method: 'POST' })))
    await fetchEmails(selectedAccountId)
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center text-gray-400">
        <div className="text-center">
          <div className="text-3xl mb-2">📬</div>
          <div>加载中...</div>
        </div>
      </div>
    )
  }

  if (view === 'settings') {
    return (
      <div className="min-h-screen bg-gray-100 flex justify-center">
        <div className="w-full max-w-2xl flex flex-col" style={{ minHeight: '100dvh' }}>
          <SettingsPage
            accounts={accounts}
            onBack={() => setView('inbox')}
            onAddAccount={() => { setView('inbox'); setShowAddAccount(true) }}
            onDeleteAccount={handleDeleteAccount}
          />
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-white flex justify-center">
      <div className="w-full max-w-2xl flex flex-col relative" style={{ minHeight: '100dvh' }}>

        {drawerOpen && (
          <div className="fixed inset-0 z-40 flex">
            <div className="w-4/5 max-w-xs h-full shadow-xl">
              <Drawer
                accounts={accounts}
                selectedAccountId={selectedAccountId}
                onSelectAccount={id => { setSelectedAccountId(id); setDrawerOpen(false) }}
                onAddAccount={() => { setDrawerOpen(false); setShowAddAccount(true) }}
                onSettings={() => { setDrawerOpen(false); setView('settings') }}
                onSync={() => { handleSync(); setDrawerOpen(false) }}
                onClose={() => setDrawerOpen(false)}
              />
            </div>
            <div className="flex-1 bg-black/30" onClick={() => setDrawerOpen(false)} />
          </div>
        )}

        {view === 'detail' && selectedEmail ? (
          <EmailDetail
            email={selectedEmail}
            account={getAccountById(accounts, selectedEmail.accountId)}
            onBack={() => setView('inbox')}
            onDelete={() => handleDelete(selectedEmail.id)}
            onStar={() => handleStar(selectedEmail.id)}
          />
        ) : (
          <>
            <div className="flex items-center justify-between px-4 py-3 bg-white border-b border-gray-100 sticky top-0 z-10">
              <div className="flex items-center gap-3">
                <button onClick={() => setDrawerOpen(true)}>
                  <Menu size={22} className="text-gray-700" />
                </button>
                <h1 className="text-lg font-semibold text-gray-900 truncate max-w-[180px]">{title}</h1>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto">
              {visibleEmails.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-gray-400">
                  <div className="text-4xl mb-3">📭</div>
                  <div>暂无邮件</div>
                </div>
              ) : (
                visibleEmails.map(email => (
                  <EmailItem
                    key={email.id}
                    email={email}
                    account={getAccountById(accounts, email.accountId)}
                    onClick={() => handleOpenEmail(email)}
                    onStar={() => handleStar(email.id)}
                  />
                ))
              )}
            </div>

            <button className="absolute bottom-6 right-4 w-14 h-14 bg-blue-600 rounded-full flex items-center justify-center shadow-lg">
              <Edit size={22} className="text-white" />
            </button>
          </>
        )}

        {showAddAccount && (
          <AddAccountModal
            onClose={() => setShowAddAccount(false)}
            onAdd={handleAddAccount}
          />
        )}
      </div>
    </div>
  )
}

