import { useState, useEffect, useCallback } from 'react'
import { Menu, Edit, Mail } from 'lucide-react'
import type { Account, Email, AccountType } from './types'
import EmailItem from './components/EmailItem'
import EmailDetail from './components/EmailDetail'
import Drawer from './components/Drawer'
import AddAccountModal from './components/AddAccountModal'
import SettingsPage from './components/SettingsPage'

type MobileView = 'list' | 'detail'

const TYPE_ORDER: Record<string, number> = { gmail: 0, outlook: 1, qq: 2 }

function sortAccounts(accounts: Account[]): Account[] {
  return [...accounts].sort((a, b) => (TYPE_ORDER[a.type] ?? 9) - (TYPE_ORDER[b.type] ?? 9))
}

function mapEmail(r: any): Email {
  return {
    id: r.id,
    accountId: r.account_id,
    from: r.from_addr,
    fromName: r.from_name,
    to: '',
    subject: r.subject,
    preview: r.preview,
    body: r.body ?? '',
    date: r.date,
    read: r.read === 1,
    starred: r.starred === 1,
    folder: r.folder,
  }
}

function getAccountById(accounts: Account[], id: string) {
  return accounts.find(a => a.id === id)
}

export default function App() {
  const [accounts, setAccounts] = useState<Account[]>([])
  const [emails, setEmails] = useState<Email[]>([])
  const [selectedAccountId, setSelectedAccountId] = useState<string | null>(null)
  const [selectedEmail, setSelectedEmail] = useState<Email | null>(null)
  const [mobileView, setMobileView] = useState<MobileView>('list')
  const [showSettings, setShowSettings] = useState(false)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [showAddAccount, setShowAddAccount] = useState(false)
  const [loading, setLoading] = useState(true)

  const fetchAccounts = useCallback(async () => {
    const res = await fetch('/api/accounts')
    const data = await res.json()
    setAccounts(data)
  }, [])

  const fetchEmails = useCallback(async (accountId?: string | null) => {
    const url = accountId ? `/api/emails?accountId=${accountId}` : '/api/emails'
    const res = await fetch(url)
    const data = await res.json()
    setEmails(data.map(mapEmail))
  }, [])

  useEffect(() => {
    setLoading(true)
    Promise.all([fetchAccounts(), fetchEmails(null)]).finally(() => setLoading(false))
  }, [])

  useEffect(() => { fetchEmails(selectedAccountId) }, [selectedAccountId])

  const visibleEmails = emails.filter(e => e.folder === 'inbox')
  const sortedAccounts = sortAccounts(accounts)
  const title = selectedAccountId ? getAccountById(accounts, selectedAccountId)?.email : '统一收件箱'

  async function handleOpenEmail(email: Email) {
    setSelectedEmail(email)
    setMobileView('detail')
    if (!email.read) {
      await fetch(`/api/emails/${email.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ read: true }) })
      setEmails(prev => prev.map(e => e.id === email.id ? { ...e, read: true } : e))
    }
  }

  async function handleStar(emailId: string) {
    const email = emails.find(e => e.id === emailId)
    if (!email) return
    const starred = !email.starred
    await fetch(`/api/emails/${emailId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ starred }) })
    setEmails(prev => prev.map(e => e.id === emailId ? { ...e, starred } : e))
    if (selectedEmail?.id === emailId) setSelectedEmail(e => e ? { ...e, starred } : e)
  }

  async function handleDelete(emailId: string) {
    await fetch(`/api/emails/${emailId}`, { method: 'DELETE' })
    setEmails(prev => prev.filter(e => e.id !== emailId))
    setSelectedEmail(null)
    setMobileView('list')
  }

  async function handleAddAccount(email: string, type: AccountType, credential: string) {
    const res = await fetch('/api/accounts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, type, credential }),
    })
    if (res.ok) await fetchAccounts()
  }

  async function handleDeleteAccount(id: string) {
    await fetch(`/api/accounts/${id}`, { method: 'DELETE' })
    await fetchAccounts()
    if (selectedAccountId === id) setSelectedAccountId(null)
  }

  async function handleSync() {
    await Promise.all(accounts.map(a => fetch(`/api/emails/sync/${a.id}`, { method: 'POST' })))
    await fetchEmails(selectedAccountId)
  }

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center text-gray-400">
        <div className="text-center"><div className="text-3xl mb-2">📬</div><div>加载中...</div></div>
      </div>
    )
  }

  if (showSettings) {
    return (
      <div className="h-screen bg-gray-100 overflow-y-auto">
        <div className="max-w-2xl mx-auto">
