        </button>
        <h1 className="text-base font-semibold text-gray-900 truncate">{title}</h1>
      </div>
      <div className="flex-1 overflow-y-auto">
        {visibleEmails.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-gray-400">
            <div className="text-4xl mb-3">📭</div>
            <div>暂无邮件</div>
          </div>
        ) : (
          visibleEmails.map(email => (
            <EmailItem
              key={email.id}
              email={email}
              account={getAccountById(accounts, email.accountId)}
              onClick={() => handleOpenEmail(email)}
              onStar={() => handleStar(email.id)}
            />
          ))
        )}
      </div>
      <button className="absolute bottom-6 right-4 w-14 h-14 bg-blue-600 rounded-full flex items-center justify-center shadow-lg md:hidden">
        <Edit size={22} className="text-white" />
      </button>
    </div>
  )

  const detailPanel = selectedEmail ? (
    <EmailDetail
      email={selectedEmail}
      account={getAccountById(accounts, selectedEmail.accountId)}
      onBack={() => { setSelectedEmail(null); setMobileView('list') }}
      onDelete={() => handleDelete(selectedEmail.id)}
      onStar={() => handleStar(selectedEmail.id)}
    />
  ) : (
    // Empty state
    <div className="hidden md:flex flex-col items-center justify-center h-full text-gray-400 bg-gray-50">
      <Mail size={48} className="mb-4 text-gray-300" />
      <div className="text-base">选择一封邮件查看详情</div>
    </div>
  )

  // ── Desktop: three columns ──────────────────────────────────
  // ── Mobile: single column with view switching ───────────────

  return (
    <>
      {/* ── Desktop layout ── */}
      <div className="hidden md:flex h-screen overflow-hidden">
        {/* Col 1: accounts */}
        <div className="w-64 flex-shrink-0 border-r border-gray-200 overflow-y-auto">
          {accountPanel}
        </div>
        {/* Col 2: email list */}
        <div className="w-80 flex-shrink-0 border-r border-gray-200 relative overflow-hidden">
          {emailListPanel}
          <button className="absolute bottom-6 right-4 w-12 h-12 bg-blue-600 rounded-full flex items-center justify-center shadow-lg">
            <Edit size={20} className="text-white" />
          </button>
        </div>
        {/* Col 3: detail */}
        <div className="flex-1 overflow-hidden">
          {detailPanel}
        </div>
      </div>

      {/* ── Mobile layout ── */}
      <div className="md:hidden h-screen relative overflow-hidden">
        {/* Drawer overlay */}
        {drawerOpen && (
          <div className="fixed inset-0 z-40 flex">
            <div className="w-4/5 max-w-xs h-full shadow-xl">{accountPanel}</div>
            <div className="flex-1 bg-black/30" onClick={() => setDrawerOpen(false)} />
          </div>
        )}

        {mobileView === 'list' ? (
          <div className="h-full relative">{emailListPanel}</div>
        ) : (
          <div className="h-full">{detailPanel}</div>
        )}
      </div>

      {showAddAccount && (
        <AddAccountModal onClose={() => setShowAddAccount(false)} onAdd={handleAddAccount} />
      )}
    </>
  )
}

