import { useRef, useState } from 'react'
import { Star, Trash2 } from 'lucide-react'
import type { Email, Account } from '../types'
import { getInitials } from '../data'
import Avatar from './Avatar'

interface Props {
  email: Email
  account?: Account
  onClick: () => void
  onStar: () => void
  onDelete: () => void
  selectMode: boolean
  selected: boolean
  onLongPress: () => void
  onToggleSelect: () => void
}

export default function EmailItem({
  email, account, onClick, onStar, onDelete,
  selectMode, selected, onLongPress, onToggleSelect,
}: Props) {
  const [swipeX, setSwipeX] = useState(0)
  const [swiping, setSwiping] = useState(false)
  const touchStartX = useRef(0)
  const touchStartY = useRef(0)
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const didLongPress = useRef(false)

  const SWIPE_THRESHOLD = 80

  function onTouchStart(e: React.TouchEvent) {
    touchStartX.current = e.touches[0].clientX
    touchStartY.current = e.touches[0].clientY
    didLongPress.current = false
    longPressTimer.current = setTimeout(() => {
      didLongPress.current = true
      onLongPress()
    }, 500)
  }

  function onTouchMove(e: React.TouchEvent) {
    const dx = e.touches[0].clientX - touchStartX.current
    const dy = e.touches[0].clientY - touchStartY.current
    if (Math.abs(dy) > Math.abs(dx)) {
      clearTimeout(longPressTimer.current!)
      return
    }
    if (dx < 0) {
      clearTimeout(longPressTimer.current!)
      setSwiping(true)
      setSwipeX(Math.max(dx, -SWIPE_THRESHOLD))
    }
  }

  function onTouchEnd() {
    clearTimeout(longPressTimer.current!)
    if (swipeX <= -SWIPE_THRESHOLD) {
      setSwipeX(-SWIPE_THRESHOLD)
    } else {
      setSwipeX(0)
    }
    setSwiping(false)
  }

  function handleClick() {
    if (swipeX !== 0) { setSwipeX(0); return }
    if (didLongPress.current) return
    if (selectMode) { onToggleSelect(); return }
    onClick()
  }

  return (
    <div className="relative overflow-hidden border-b border-gray-100">
      {/* Swipe delete background */}
      <div className="absolute inset-y-0 right-0 flex items-center justify-end bg-red-500 px-5">
        <Trash2 size={20} className="text-white" />
      </div>

      {/* Main row */}
      <div
        className={`flex items-start gap-3 px-4 py-3 bg-white cursor-pointer select-none transition-colors
          ${selected ? 'bg-blue-50' : 'hover:bg-gray-50 active:bg-gray-100'}`}
        style={{
          transform: `translateX(${swipeX}px)`,
          transition: swiping ? 'none' : 'transform 0.2s ease',
        }}
        onClick={handleClick}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        {/* Checkbox or Avatar */}
        {selectMode ? (
          <div className={`w-9 h-9 rounded-full border-2 flex items-center justify-center flex-shrink-0 mt-0.5
            ${selected ? 'bg-blue-500 border-blue-500' : 'border-gray-300'}`}>
            {selected && <span className="text-white text-xs font-bold">✓</span>}
          </div>
        ) : (
          <Avatar text={getInitials(email.fromName || email.from)} color={account?.color || '#888'} />
        )}

        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-1.5 min-w-0">
              {!email.read && <span className="w-1.5 h-1.5 rounded-full bg-blue-500 flex-shrink-0" />}
              <span className={`truncate text-sm ${!email.read ? 'font-semibold text-gray-900' : 'text-gray-700'}`}>
                {email.subject}
              </span>
            </div>
            <span className="text-xs text-gray-400 flex-shrink-0">{email.date}</span>
          </div>
          <div className="text-xs text-gray-500 truncate mt-0.5">
            <span className="font-medium text-gray-600">{email.fromName}</span>
            {' – '}{email.preview}
          </div>
        </div>

        {!selectMode && (
          <button onClick={e => { e.stopPropagation(); onStar() }} className="flex-shrink-0 mt-0.5">
            <Star size={18} className={email.starred ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'} />
          </button>
        )}
      </div>

      {/* Swipe delete button (revealed) */}
      {swipeX <= -SWIPE_THRESHOLD && (
        <button
          className="absolute inset-y-0 right-0 w-20 bg-red-500 flex items-center justify-center"
          onClick={e => { e.stopPropagation(); setSwipeX(0); onDelete() }}
        >
          <Trash2 size={20} className="text-white" />
        </button>
      )}
    </div>
  )
}

