import { useState } from 'react'
import { ArrowLeft, Settings, Mail, Plus, ChevronDown, ChevronUp, Trash2, Upload, Download } from 'lucide-react'
import type { Account } from '../types'
import { useSettings } from '../SettingsContext'

interface Props {
  accounts: Account[]
  onBack: () => void
  onAddAccount: () => void
  onDeleteAccount: (id: string) => void
}

export default function SettingsPage({ accounts, onBack, onAddAccount, onDeleteAccount }: Props) {
  const [generalOpen, setGeneralOpen] = useState(false)
  const { theme, setTheme, fontSize, setFontSize } = useSettings()
  const [exportMsg, setExportMsg] = useState('')
  const [importMsg, setImportMsg] = useState('')

  async function handleExport() {
    const res = await fetch('/api/migrate/bundle', { credentials: 'include' })
    if (!res.ok) { setExportMsg('✗ 导出失败'); return }
    const blob = await res.blob()
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'imail_accounts.zip'
    a.click()
    URL.revokeObjectURL(url)
    setExportMsg('✓ 已下载')
  }

  async function handleImport() {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = '.zip'
    input.onchange = async () => {
      const file = input.files?.[0]
      if (!file) return
      if (!confirm('导入将合并账号数据，确认继续？')) return
      setImportMsg('导入中...')
      const res = await fetch('/api/migrate/bundle', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/zip' },
        body: file,
      })
      const d = await res.json()
      setImportMsg(d.ok ? `✓ 已导入 ${d.imported} 个账号` : `✗ ${d.error}`)
    }
    input.click()
  }

  return (
    <div className="flex flex-col h-full bg-gray-100 text-[0.8em]">
      <div onClick={onBack} className="flex items-center gap-3 px-4 py-3 bg-gray-100 border-b border-gray-200 cursor-pointer hover:bg-gray-200">
        <ArrowLeft size={22} className="text-gray-600" />
        <h1 className="text-[1.1em] font-semibold text-gray-900">设置</h1>
      </div>

      <div className="flex-1 overflow-y-auto">
        {/* General */}
        <div className="bg-white mt-2">
          <button
            className="w-full flex items-center gap-3 px-4 py-4 hover:bg-gray-50"
            onClick={() => setGeneralOpen(o => !o)}
          >
            <Settings size={20} className="text-gray-500" />
            <span className="flex-1 text-left text-gray-800">常规设置</span>
            {generalOpen ? <ChevronUp size={18} className="text-gray-400" /> : <ChevronDown size={18} className="text-gray-400" />}
          </button>

          {generalOpen && (
            <div className="border-t border-gray-100 px-4 py-3 space-y-4">
              {/* Font size */}
              <div className="flex items-center justify-between">
                <span className="text-[1em] text-gray-700">字体大小</span>
                <div className="flex gap-1">
                  {(['small', 'medium', 'large'] as const).map(s => (
                    <button
                      key={s}
                      onClick={() => setFontSize(s)}
                      className={`px-3 py-1 rounded text-[0.85em] border ${fontSize === s ? 'bg-blue-500 text-white border-blue-500' : 'text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                    >
                      {s === 'small' ? '小' : s === 'medium' ? '中' : '大'}
                    </button>
                  ))}
                </div>
              </div>

              {/* Theme */}
              <div className="flex items-center justify-between">
                <span className="text-[1em] text-gray-700">主题</span>
                <div className="flex gap-1">
                  {(['light', 'dark'] as const).map(t => (
                    <button
                      key={t}
                      onClick={() => setTheme(t)}
                      className={`px-3 py-1 rounded text-[0.85em] border ${theme === t ? 'bg-blue-500 text-white border-blue-500' : 'text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                    >
                      {t === 'light' ? '浅色' : '深色'}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Accounts section */}
        <div className="mt-4">
          <div className="px-4 py-2 text-[1em] font-semibold text-blue-500">账号</div>
          <div className="bg-white">
            {accounts.map(acc => (
              <div key={acc.id} className="flex items-center gap-3 px-4 py-4 border-b border-gray-50">
                <Mail size={20} className="text-gray-400" />
                <div className="flex-1 min-w-0">
                  <div className="text-[1em] font-medium text-gray-800 truncate">{acc.email}</div>
                  <div className="text-[0.85em] text-gray-400 truncate">{acc.type}</div>
                </div>
                <button
                  onClick={() => { if (confirm(`删除账号 ${acc.email}？`)) onDeleteAccount(acc.id) }}
                  className="p-1 text-gray-300 hover:text-red-500"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
            <button
              onClick={onAddAccount}
              className="w-full flex items-center gap-3 px-4 py-4 hover:bg-gray-50"
            >
              <Plus size={20} className="text-gray-400" />
              <span className="text-gray-700">添加账号</span>
            </button>
          </div>
        </div>

        {/* Migration */}
        <div className="mt-4 mb-6">
          <div className="px-4 py-2 text-[1em] font-semibold text-blue-500">数据迁移</div>
          <div className="bg-white divide-y divide-gray-50">
            <div className="px-4 py-3 flex items-center justify-between">
              <div>
                <div className="text-[0.95em] text-gray-700">导出账号</div>
                <div className="text-[0.8em] text-gray-400">打包账号配置为 zip 下载</div>
                {exportMsg && <div className="text-[0.8em] text-gray-500 mt-1">{exportMsg}</div>}
              </div>
              <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-2 bg-blue-500 text-white rounded-lg text-[0.9em] hover:bg-blue-600">
                <Download size={14} /> 导出
              </button>
            </div>
            <div className="px-4 py-3 flex items-center justify-between">
              <div>
                <div className="text-[0.95em] text-gray-700">导入账号</div>
                <div className="text-[0.8em] text-gray-400">选择 zip 文件恢复账号配置</div>
                {importMsg && <div className="text-[0.8em] text-gray-500 mt-1">{importMsg}</div>}
              </div>
              <button onClick={handleImport} className="flex items-center gap-1.5 px-3 py-2 bg-green-500 text-white rounded-lg text-[0.9em] hover:bg-green-600">
                <Upload size={14} /> 导入
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useRef, useState } from 'react'
import { Star, Trash2, Mail, MailOpen } from 'lucide-react'
import type { Email, Account } from '../types'
import { getInitials } from '../data'
import Avatar from './Avatar'

function formatDate(raw: string): string {
  if (!raw) return ''
  const d = new Date(raw)
  if (isNaN(d.getTime())) return raw
  const now = new Date()
  const isToday = d.toDateString() === now.toDateString()
  if (isToday) {
    return d.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })
  }
  return d.toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit' }) +
    ' ' + d.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })
}

interface Props {
  email: Email
  account?: Account
  onClick: () => void
  onStar: () => void
  onDelete: () => void
  onToggleRead: () => void
  selectMode: boolean
  selected: boolean
  onLongPress: () => void
  onToggleSelect: () => void
}

export default function EmailItem({
  email, account, onClick, onStar, onDelete, onToggleRead,
  selectMode, selected, onLongPress, onToggleSelect,
}: Props) {
  const [hovered, setHovered] = useState(false)
  const [swipeX, setSwipeX] = useState(0)
  const [swiping, setSwiping] = useState(false)
  const touchStartX = useRef(0)
  const touchStartY = useRef(0)
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const didLongPress = useRef(false)
  const SWIPE_THRESHOLD = 80

  // ── Touch handlers (mobile) ──────────────────────────────
  function onTouchStart(e: React.TouchEvent) {
    touchStartX.current = e.touches[0].clientX
    touchStartY.current = e.touches[0].clientY
    didLongPress.current = false
    longPressTimer.current = setTimeout(() => {
      didLongPress.current = true
      onLongPress()
    }, 500)
  }

  function onTouchMove(e: React.TouchEvent) {
    const dx = e.touches[0].clientX - touchStartX.current
    const dy = e.touches[0].clientY - touchStartY.current
    if (Math.abs(dy) > Math.abs(dx)) { clearTimeout(longPressTimer.current!); return }
    if (dx < 0) {
      clearTimeout(longPressTimer.current!)
      setSwiping(true)
      setSwipeX(Math.max(dx, -SWIPE_THRESHOLD))
    }
  }

  function onTouchEnd() {
    clearTimeout(longPressTimer.current!)
    setSwipeX(swipeX <= -SWIPE_THRESHOLD ? -SWIPE_THRESHOLD : 0)
    setSwiping(false)
  }

  function handleClick() {
    if (swipeX !== 0) { setSwipeX(0); return }
    if (didLongPress.current) return
    if (selectMode) { onToggleSelect(); return }
    onClick()
  }

  // ── Checkbox (desktop hover or selectMode) ───────────────
  const showCheckbox = selectMode || hovered

  return (
    <div
      className="relative overflow-hidden border-b border-gray-100"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      {/* Swipe delete bg (mobile) */}
      <div className="absolute inset-y-0 right-0 flex items-center justify-end bg-red-500 px-5">
        <Trash2 size={18} className="text-white" />
      </div>

      {/* Main row */}
      <div
        className={`flex items-center gap-3 px-4 py-3 bg-white cursor-pointer select-none transition-colors
          ${selected ? 'bg-blue-50' : hovered ? 'bg-gray-50' : ''}`}
        style={{ transform: `translateX(${swipeX}px)`, transition: swiping ? 'none' : 'transform 0.2s ease' }}
        onClick={handleClick}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        {/* Checkbox (desktop hover / selectMode) or Avatar */}
        <div className="flex-shrink-0 w-7 h-7 flex items-center justify-center">
          {showCheckbox ? (
            <button
              onClick={e => { e.stopPropagation(); selectMode ? onToggleSelect() : onLongPress() }}
              className={`w-4 h-4 rounded-full border-2 flex items-center justify-center transition-colors
                ${selected ? 'bg-blue-500 border-blue-500' : 'border-gray-300 hover:border-blue-400'}`}
            >
              {selected && <span className="text-white text-[9px] leading-none">✓</span>}
            </button>
          ) : (
            <Avatar text={getInitials(email.fromName || email.from)} color={account?.color || '#888'} />
          )}
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-1 min-w-0">
              {!email.read && <span className="w-1 h-1 rounded-full bg-blue-500 flex-shrink-0" />}
              <span className={`truncate text-[0.8em] ${!email.read ? 'font-semibold text-gray-900' : 'text-gray-600'}`}>
                {email.subject}
              </span>
            </div>
            <span className="text-xs text-gray-400 flex-shrink-0">{formatDate(email.date)}</span>
          </div>
          <div className="text-[11px] text-gray-400 truncate mt-0.5">
            <span className="font-normal text-gray-400">{email.fromName}</span>
            {' – '}{email.preview}
          </div>
        </div>

        {!selectMode && (
          <div className="flex items-center gap-1 flex-shrink-0">
            {hovered && (
              <button onClick={e => { e.stopPropagation(); onToggleRead() }} className="p-0.5 text-gray-400 hover:text-blue-500 transition-colors">
                {email.read ? <Mail size={15} /> : <MailOpen size={15} />}
              </button>
            )}
            <button onClick={e => { e.stopPropagation(); onStar() }}>
              <Star size={16} className={email.starred ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'} />
            </button>
          </div>
        )}
      </div>

      {/* Swipe delete button */}
      {swipeX <= -SWIPE_THRESHOLD && (
        <button
          className="absolute inset-y-0 right-0 w-20 bg-red-500 flex items-center justify-center"
          onClick={e => { e.stopPropagation(); setSwipeX(0); onDelete() }}
        >
          <Trash2 size={18} className="text-white" />
        </button>
      )}
    </div>
  )
}

import { useState } from 'react'
import { RefreshCw, Plus, Settings, ChevronRight, ChevronLeft, Inbox, Send, FileText, Trash2, AlertCircle } from 'lucide-react'
import type { Account } from '../types'

export const ALL_INBOXES = '__all__'

export function parseFolderId(id: string | null) {
  if (!id || !id.includes('::')) return { accountId: id, folder: 'inbox' }
  const [accountId, folder] = id.split('::')
  return { accountId, folder }
}

const FOLDERS = [
  { key: 'inbox',  label: '收件箱',  icon: Inbox },
  { key: 'sent',   label: '已发送',  icon: Send },
  { key: 'draft',  label: '草稿箱',  icon: FileText },
  { key: 'spam',   label: '垃圾邮件', icon: AlertCircle },
  { key: 'trash',  label: '已删除',  icon: Trash2 },
]

const TYPE_LABELS: Record<string, string> = { gmail: 'Gmail', outlook: 'Outlook', qq: 'QQ 邮箱' }

function ProviderLogo({ type, email, size = 6 }: { type: string, email?: string, size?: number }) {
  const isHotmail = email?.toLowerCase().includes('hotmail')
  const isLive = email?.toLowerCase().endsWith('@live.com')

  const src = isLive ? '/live.png'
    : isHotmail ? '/hotmail.png'
    : type === 'gmail' ? '/gmail.png'
    : type === 'outlook' ? '/outlook.png'
    : type === 'qq' ? '/qq.png'
    : null

  const px = size * 4
  if (!src) return <div style={{ width: px, height: px }} className="rounded-lg bg-gray-200 flex-shrink-0" />
  return <img src={src} alt={type} style={{ width: px, height: px }} className="object-contain flex-shrink-0" />
}

function shortEmail(email: string) { return email.split('@')[0] }

type View = { level: 'root' } | { level: 'accounts'; type: string } | { level: 'folders'; account: Account }

interface Props {
  accounts: Account[]
  selectedAccountId: string | null
  onSelectAccount: (id: string | null) => void
  onAddAccount: () => void
  onSettings: () => void
  onSync: () => void
  onClose: () => void
  syncing?: boolean
}

export default function Drawer({ accounts, selectedAccountId, onSelectAccount, onAddAccount, onSettings, onSync, onClose, syncing }: Props) {
  const [view, setView] = useState<View>({ level: 'root' })
  const { accountId: selAccountId } = parseFolderId(selectedAccountId)

  const types = (['gmail', 'outlook', 'qq'] as const).filter(t => accounts.some(a => a.type === t))

  return (
    <div className="flex flex-col bg-white" style={{ height: '100dvh' }}>
      {/* Header */}
      <div
        className={`flex items-center gap-2 px-4 py-4 border-b border-gray-100 ${view.level !== 'root' ? 'cursor-pointer hover:bg-gray-50' : ''}`}
        onClick={() => {
          if (view.level === 'folders') setView({ level: 'accounts', type: view.account.type })
          else if (view.level === 'accounts') setView({ level: 'root' })
        }}
      >
        {view.level !== 'root' && <ChevronLeft size={20} className="text-gray-500 flex-shrink-0" />}
        <span className="font-normal text-gray-600">
          {view.level === 'root' ? <span>@iMail <span className="text-gray-400 text-[0.85em]">by mrlees</span></span>
            : view.level === 'accounts' ? TYPE_LABELS[view.type]
            : shortEmail(view.account.email)}
        </span>
      </div>

      <div className="flex-1 overflow-y-auto">
        {/* Root: all inboxes + type groups */}
        {view.level === 'root' && (
          <>
            <button
              onClick={() => { onSelectAccount(ALL_INBOXES); onClose() }}
              className={`w-full flex items-center gap-3 px-4 py-3 transition-colors ${selectedAccountId === ALL_INBOXES ? 'bg-blue-50' : 'hover:bg-gray-50'}`}
            >
              <div className={`w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 ${selectedAccountId === ALL_INBOXES ? 'bg-blue-500' : 'bg-gray-200'}`}>
                <Inbox size={14} className="text-white" />
              </div>
              <span className={`flex-1 text-left text-[0.9em] font-medium ${selectedAccountId === ALL_INBOXES ? 'text-blue-500' : 'text-gray-800'}`}>所有收件箱</span>
            </button>

            {types.map(type => {
              const bgColor = { gmail: 'rgba(234,67,53,0.08)', outlook: 'rgba(0,120,212,0.08)', qq: 'rgba(18,183,245,0.08)' }[type]
              const textColor = { gmail: '#c0392b', outlook: '#0063b1', qq: '#0891b2' }[type]
              return (
                <button key={type} onClick={() => setView({ level: 'accounts', type })}
                  className="w-full flex items-center gap-3 px-4 py-3 transition-colors hover:brightness-95"
                  style={{ backgroundColor: bgColor }}>
                  <div className="w-6 h-6 flex items-center justify-center flex-shrink-0">
                    <ProviderLogo type={type} size={6} />
                  </div>
                  <span className="flex-1 text-left text-[0.9em] font-medium" style={{ color: textColor }}>{TYPE_LABELS[type]}</span>
                  <ChevronRight size={16} className="text-gray-400" />
                </button>
              )
            })}
          </>
        )}

        {/* Accounts under a type */}
        {view.level === 'accounts' && accounts.filter(a => a.type === view.type).map(acc => (
          <button key={acc.id} onClick={() => setView({ level: 'folders', account: acc })}
            className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 transition-colors ${selAccountId === acc.id ? 'bg-blue-50' : ''}`}>
            <ProviderLogo type={acc.type} email={acc.email} />
            <span className={`flex-1 text-left text-[0.9em] truncate ${selAccountId === acc.id ? 'text-blue-500 font-medium' : 'text-gray-700'}`}>
              {shortEmail(acc.email)}
            </span>
            {acc.unread > 0 && <span className="text-[0.78em] font-medium text-gray-400">{acc.unread}</span>}
            <ChevronRight size={16} className="text-gray-400" />
          </button>
        ))}

        {/* Folders under an account */}
        {view.level === 'folders' && (() => {
          const baseColor = { gmail: '234,67,53', outlook: '0,120,212', qq: '18,183,245' }[view.account.type] || '99,102,241'
          return FOLDERS.map((f, i) => {
            const folderId = `${view.account.id}::${f.key}`
            const isSelected = selectedAccountId === folderId
            const Icon = f.icon
            const alpha = (0.12 - i * 0.02).toFixed(2)
            const unread = f.key === 'inbox' ? (view.account.unread || 0) : 0
            const total = f.key === 'inbox' ? (view.account.folderCounts?.['inbox_total'] || 0) : 0
            return (
              <button key={f.key} onClick={() => { onSelectAccount(folderId); onClose() }}
                className={`w-full flex items-center gap-3 px-4 py-3 transition-colors ${isSelected ? 'text-blue-500' : 'text-gray-600 hover:brightness-95'}`}
                style={{ backgroundColor: isSelected ? `rgba(${baseColor},0.18)` : `rgba(${baseColor},${alpha})` }}>
                <Icon size={16} className="flex-shrink-0" />
                <span className="flex-1 text-left text-[0.9em]">{f.label}</span>
                {f.key === 'inbox' && (
                  <span className="text-[0.75em] text-gray-400">
                    {total > 0 ? `${unread}/${total}` : unread > 0 ? unread : ''}
                  </span>
                )}
              </button>
            )
          })
        })()}
      </div>

      <div className="border-t border-gray-100 pb-4">
        <button onClick={onSync} disabled={syncing} className="w-full flex items-center gap-3 px-6 py-3 hover:bg-gray-50 text-gray-800">
          <RefreshCw size={14} className={syncing ? 'spinning' : ''} /> <span className="text-[0.7em]">同步全部账号</span>
        </button>
        <button onClick={onAddAccount} className="w-full flex items-center gap-3 px-6 py-3 hover:bg-gray-50 text-gray-800">
          <Plus size={14} /> <span className="text-[0.7em]">添加账号</span>
        </button>
        <button onClick={onSettings} className="w-full flex items-center gap-3 px-6 py-3 hover:bg-gray-50 text-gray-800">
          <Settings size={14} /> <span className="text-[0.7em]">设置</span>
        </button>
      </div>
    </div>
  )
}

import { useState } from 'react'
import { ArrowLeft } from 'lucide-react'
import type { AccountType } from '../types'

interface Props {
  onClose: () => void
  onAdd: (email: string, type: AccountType, credential: string) => void
}

const PROVIDERS = [
  { type: 'gmail' as AccountType, label: 'Gmail', hint: '16位应用专用密码', placeholder: 'xxxx xxxx xxxx xxxx', logo: '/gmail.png' },
  { type: 'outlook' as AccountType, label: 'Outlook / Hotmail / Live', hint: 'OAuth2 授权登录', placeholder: '', logo: '/outlook.png' },
  { type: 'qq' as AccountType, label: 'QQ 邮箱', hint: 'QQ 邮箱授权码', placeholder: '16位授权码', logo: '/qq.png' },
]

export default function AddAccountPage({ onClose, onAdd }: Props) {
  const [step, setStep] = useState<'pick' | 'form'>('pick')
  const [provider, setProvider] = useState<typeof PROVIDERS[0] | null>(null)
  const [email, setEmail] = useState('')
  const [credential, setCredential] = useState('')

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (!provider) return
    onAdd(email, provider.type, credential)
    onClose()
  }

  return (
    <div className="fixed inset-0 z-50 bg-gray-50 flex flex-col">
      {/* Header */}
      <div
        onClick={step === 'form' ? () => setStep('pick') : onClose}
        className="flex items-center gap-3 px-4 py-3 bg-white border-b border-gray-200 cursor-pointer hover:bg-gray-50"
      >
        <ArrowLeft size={22} className="text-gray-600" />
        <h1 className="text-base font-semibold text-gray-900">
          {step === 'pick' ? '添加账号' : `添加 ${provider?.label}`}
        </h1>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-6 max-w-lg mx-auto w-full">
        {step === 'pick' && (
          <div className="flex flex-col gap-3">
            {PROVIDERS.map(p => (
              <button
                key={p.type}
                onClick={() => { setProvider(p); setStep('form') }}
                className="flex items-center gap-4 p-4 bg-white border border-gray-200 rounded-xl hover:bg-gray-50 text-left"
              >
                <div className="w-10 h-10 rounded-lg bg-gray-50 border border-gray-100 flex items-center justify-center flex-shrink-0">
                  <img src={p.logo} alt={p.label} className="w-6 h-6 object-contain" />
                </div>
                <div>
                  <div className="font-medium text-gray-800">{p.label}</div>
                  <div className="text-xs text-gray-500 mt-0.5">{p.hint}</div>
                </div>
              </button>
            ))}
          </div>
        )}

        {step === 'form' && provider && (
          <form onSubmit={handleSubmit} className="flex flex-col gap-5">
            <div>
              <label className="text-sm text-gray-600 mb-1.5 block">邮箱地址</label>
              <input
                type="email" required value={email} onChange={e => setEmail(e.target.value)}
                placeholder={`your@${provider.type === 'qq' ? 'qq.com' : provider.type === 'gmail' ? 'gmail.com' : 'outlook.com'}`}
                className="w-full border border-gray-300 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-blue-500"
              />
            </div>

            {provider.type === 'outlook' ? (
              <button type="button" className="w-full py-3 bg-blue-600 text-white rounded-xl font-medium"
                onClick={() => { window.location.href = '/api/emails/oauth/outlook' }}>
                使用 Microsoft 授权登录
              </button>
            ) : (
              <>
                <div>
                  <label className="text-sm text-gray-600 mb-1.5 block">{provider.hint}</label>
                  <input
                    type="password" required value={credential} onChange={e => setCredential(e.target.value)}
                    placeholder={provider.placeholder}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-blue-500"
                  />
                </div>
                <button type="submit" className="w-full py-3 bg-blue-600 text-white rounded-xl font-medium">
                  添加账号
                </button>
              </>
            )}
          </form>
        )}
      </div>
    </div>
  )
}

