const router = require('express').Router()
const accountsDb = require('../accountsDb')
const db = require('../db')
const { randomUUID } = require('crypto')

const COLORS = ['#4A90D9','#E91E8C','#FF7043','#8BC34A','#9C27B0','#26A69A','#FF9800','#607D8B']

router.get('/', (req, res) => {
  const accounts = accountsDb.prepare('SELECT id, email, type, color FROM accounts').all()
  const unreadMap = Object.fromEntries(
    db.prepare('SELECT account_id, COUNT(*) as n FROM emails WHERE read=0 AND deleted=0 GROUP BY account_id').all()
      .map(r => [r.account_id, r.n])
  )
  const folderRows = db.prepare('SELECT account_id, folder, COUNT(*) as n FROM emails WHERE deleted=0 GROUP BY account_id, folder').all()
  const folderMap = {}
  for (const r of folderRows) {
    if (!folderMap[r.account_id]) folderMap[r.account_id] = {}
    folderMap[r.account_id][r.folder] = r.n
  }
  res.json(accounts
    .sort((a, b) => a.email.localeCompare(b.email))
    .map(a => ({ ...a, unread: unreadMap[a.id] || 0, folderCounts: folderMap[a.id] || {} }))
  )
})

router.post('/', (req, res) => {
  const { email, type, credential } = req.body
  if (!email || !type || !credential) return res.status(400).json({ error: 'missing fields' })
  const count = accountsDb.prepare('SELECT COUNT(*) as n FROM accounts').get().n
  const id = randomUUID()
  const color = COLORS[count % COLORS.length]
  accountsDb.prepare('INSERT INTO accounts (id, email, type, color, config) VALUES (?, ?, ?, ?, ?)')
    .run(id, email, type, color, JSON.stringify({ credential }))
  res.status(201).json({ id, email, type, color, unread: 0 })
})

router.delete('/:id', (req, res) => {
  db.prepare('DELETE FROM emails WHERE account_id = ?').run(req.params.id)
  accountsDb.prepare('DELETE FROM accounts WHERE id = ?').run(req.params.id)
  res.json({ ok: true })
})

router.get('/:id/config', (req, res) => {
  const row = accountsDb.prepare('SELECT config FROM accounts WHERE id = ?').get(req.params.id)
  if (!row) return res.status(404).json({ error: 'not found' })
  res.json(JSON.parse(row.config))
})

module.exports = router

const router = require('express').Router()
const db = require('../db')
const accountsDb = require('../accountsDb')
const { convert } = require('html-to-text')
const toPlainText = (html) => html ? convert(html, { wordwrap: false, selectors: [{ selector: 'img', format: 'skip' }, { selector: 'a', options: { ignoreHref: true } }] }).slice(0, 5000) : ''
const { fetchEmails } = require('../imap')
const { getAuthUrl, handleCallback, getAccessToken } = require('../outlook')
const { randomUUID } = require('crypto')
const nodemailer = require('nodemailer')

// POST /api/emails/send
router.post('/send', async (req, res) => {
  const { fromAccountId, to, bcc, subject, body } = req.body
  if (!fromAccountId || !to || !subject) return res.status(400).json({ error: 'missing fields' })

  const account = accountsDb.prepare('SELECT * FROM accounts WHERE id = ?').get(fromAccountId)
  if (!account) return res.status(404).json({ error: 'account not found' })

  const config = JSON.parse(account.config)
  let transporter

  if (account.type === 'outlook') {
    const accessToken = await getAccessToken(account.id)
    transporter = nodemailer.createTransport({
      host: 'smtp.office365.com',
      port: 587,
      secure: false,
      auth: { type: 'OAuth2', user: account.email, accessToken },
    })
  } else {
    const smtpHost = account.type === 'gmail' ? 'smtp.gmail.com' : 'smtp.qq.com'
    const smtpPort = account.type === 'gmail' ? 587 : 587
    transporter = nodemailer.createTransport({
      host: smtpHost, port: smtpPort, secure: false,
      auth: { user: account.email, pass: config.credential },
    })
  }

  await transporter.sendMail({
    from: account.email, to, bcc: bcc || undefined,
    subject, text: body, html: body,
  })

  res.json({ ok: true })
})

// GET /api/emails?accountId=&folder=inbox&page=1
router.get('/', (req, res) => {
  const { accountId, folder = 'inbox', page = 1 } = req.query
  const limit = 50
  const offset = (page - 1) * limit

  let rows
  if (accountId) {
    rows = db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder
      FROM emails WHERE account_id = ? AND folder = ? AND deleted = 0
      ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(accountId, folder, limit, offset)
  } else {
    rows = db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder
      FROM emails WHERE folder = ? AND deleted = 0
      ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(folder, limit, offset)
  }
  res.json(rows)
})

// GET /api/emails/:id
router.get('/:id', (req, res) => {
  const row = db.prepare('SELECT * FROM emails WHERE id = ?').get(req.params.id)
  if (!row) return res.status(404).json({ error: 'not found' })
  // auto mark read
  db.prepare('UPDATE emails SET read = 1 WHERE id = ?').run(req.params.id)
  res.json({ ...row, read: 1 })
})

// PATCH /api/emails/:id  { read, starred, folder }
router.patch('/:id', (req, res) => {
  const { read, starred, folder } = req.body
  const fields = []
  const vals = []
  if (read !== undefined)    { fields.push('read = ?');    vals.push(read ? 1 : 0) }
  if (starred !== undefined) { fields.push('starred = ?'); vals.push(starred ? 1 : 0) }
  if (folder !== undefined)  { fields.push('folder = ?');  vals.push(folder) }
  if (!fields.length) return res.status(400).json({ error: 'nothing to update' })
  vals.push(req.params.id)
  db.prepare(`UPDATE emails SET ${fields.join(', ')} WHERE id = ?`).run(...vals)
  res.json({ ok: true })
})

// DELETE /api/emails/:id  (soft delete)
router.delete('/:id', (req, res) => {
  db.prepare('UPDATE emails SET deleted = 1 WHERE id = ?').run(req.params.id)
  res.json({ ok: true })
})

// POST /api/emails/sync/:accountId
router.post('/sync/:accountId', async (req, res) => {
  const account = accountsDb.prepare('SELECT * FROM accounts WHERE id = ?').get(req.params.accountId)
  if (!account) return res.status(404).json({ error: 'account not found' })

  const config = JSON.parse(account.config)

  if (account.type === 'outlook') {
    const token = await getAccessToken(account.id)
    const nodeFetch = (await import('node-fetch')).default
    let url = 'https://graph.microsoft.com/v1.0/me/mailFolders/inbox/messages?$top=999&$orderby=receivedDateTime desc&$select=id,subject,from,bodyPreview,body,receivedDateTime,isRead'
    let count = 0
    while (url) {
      const resp = await nodeFetch(url, { headers: { Authorization: `Bearer ${token}` } })
      const data = await resp.json()
      for (const msg of (data.value || [])) {
        const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ?').get(account.id, msg.id)
        if (!existing) {
          db.prepare(`INSERT INTO emails (id, account_id, uid, folder, from_addr, from_name, subject, preview, body, date, read, raw_date)
            VALUES (?, ?, ?, 'inbox', ?, ?, ?, ?, ?, ?, ?, ?)`)
            .run(randomUUID(), account.id, msg.id,
              msg.from?.emailAddress?.address || '',
              msg.from?.emailAddress?.name || '',
              msg.subject || '(无主题)',
              (msg.bodyPreview || '').slice(0, 100),
              msg.body?.content ? toPlainText(msg.body.content) : '',
              msg.receivedDateTime || '',
              msg.isRead ? 1 : 0,
              msg.receivedDateTime ? new Date(msg.receivedDateTime).getTime() : 0,
            )
          count++
        }
      }
      url = data['@odata.nextLink'] || null
    }
    return res.json({ synced: count })
  }

  const count = await fetchEmails(account, config)
  res.json({ synced: count })
})

// Outlook OAuth2 flow
router.get('/oauth/outlook', async (req, res) => {
  const redirectUri = process.env.OUTLOOK_REDIRECT_URI || `${req.protocol}://${req.get('host')}/api/emails/oauth/outlook/callback`
  const url = await getAuthUrl(redirectUri)
  res.redirect(url)
})

router.get('/oauth/outlook/callback', async (req, res) => {
  const { code } = req.query
  const redirectUri = process.env.OUTLOOK_REDIRECT_URI || `${req.protocol}://${req.get('host')}/api/emails/oauth/outlook/callback`
  const result = await handleCallback(code, redirectUri)

  const email = result.account.username
  const existing = accountsDb.prepare('SELECT id FROM accounts WHERE email = ?').get(email)
  if (!existing) {
    const count = accountsDb.prepare('SELECT COUNT(*) as n FROM accounts').get().n
    const COLORS = ['#4A90D9','#E91E8C','#FF7043','#8BC34A','#9C27B0','#26A69A','#FF9800','#607D8B']
    accountsDb.prepare('INSERT INTO accounts (id, email, type, color, config) VALUES (?, ?, ?, ?, ?)')
      .run(randomUUID(), email, 'outlook', COLORS[count % COLORS.length],
        JSON.stringify({ refreshToken: result.account.homeAccountId }))
  }

  res.redirect('/?oauth=success')
})

module.exports = router

const Imap = require('imap')
const { simpleParser } = require('mailparser')
const { convert } = require('html-to-text')
const db = require('./db')
const { randomUUID } = require('crypto')

function toPlainText(html, text) {
  if (text) return text.slice(0, 5000)
  if (html) return convert(html, { wordwrap: false, selectors: [{ selector: 'img', format: 'skip' }, { selector: 'a', options: { ignoreHref: true } }] }).slice(0, 5000)
  return ''
}

const IMAP_CONFIG = {
  gmail: { host: 'imap.gmail.com', port: 993, tls: true },
  qq:    { host: 'imap.qq.com',    port: 993, tls: true },
}

const FOLDER_MAP = {
  gmail:   { inbox: 'INBOX', sent: '[Gmail]/Sent Mail', draft: '[Gmail]/Drafts', trash: '[Gmail]/Trash', spam: '[Gmail]/Spam' },
  qq:      { inbox: 'INBOX', sent: 'Sent Messages',     draft: 'Drafts',         trash: 'Deleted Messages', spam: 'Junk' },
  outlook: { inbox: 'INBOX', sent: 'Sent',              draft: 'Drafts',         trash: 'Deleted',          spam: 'Junk' },
}

function fetchFolder(imap, account, imapFolder, folderKey) {
  return new Promise((resolve) => {
    imap.openBox(imapFolder, true, (err, box) => {
      if (err || !box || box.messages.total === 0) return resolve(0)
      const fetch = imap.seq.fetch('1:*', { bodies: '', struct: true })
      const promises = []
      fetch.on('message', (msg, seqno) => {
        let uid = seqno
        const p = new Promise(res => {
          msg.on('attributes', attrs => { uid = attrs.uid })
          msg.on('body', stream => {
            simpleParser(stream, (err, parsed) => {
              if (err) return res()
              const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, uid, folderKey)
              if (!existing) {
                db.prepare(`INSERT INTO emails (id, account_id, uid, folder, from_addr, from_name, subject, preview, body, date, raw_date)
                  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
                  .run(
                    randomUUID(), account.id, uid, folderKey,
                    parsed.from?.value?.[0]?.address || '',
                    parsed.from?.value?.[0]?.name || '',
                    parsed.subject || '(无主题)',
                    (parsed.text || '').slice(0, 100).replace(/\n/g, ' '),
                    toPlainText(parsed.html, parsed.text),
                    parsed.date ? parsed.date.toISOString() : '',
                    parsed.date ? parsed.date.getTime() : 0,
                  )
              }
              res()
            })
          })
        })
        promises.push(p)
      })
      fetch.once('end', async () => { await Promise.all(promises); resolve(promises.length) })
      fetch.once('error', () => resolve(0))
    })
  })
}

function fetchEmails(account, config) {
  return new Promise((resolve, reject) => {
    const imapCfg = IMAP_CONFIG[account.type]
    if (!imapCfg) return reject(new Error('unsupported type'))

    const imap = new Imap({
      user: account.email,
      password: config.credential,
      ...imapCfg,
      tlsOptions: { rejectUnauthorized: false },
    })

    imap.once('ready', async () => {
      const folders = FOLDER_MAP[account.type] || FOLDER_MAP.qq
      let total = 0
      for (const [folderKey, imapFolder] of Object.entries(folders)) {
        try {
          const n = await fetchFolder(imap, account, imapFolder, folderKey)
          total += n
        } catch (e) {
          // skip unavailable folders
        }
      }
      imap.end()
      resolve(total)
    })

    imap.once('error', reject)
    imap.connect()
  })
}

module.exports = { fetchEmails }

const { ConfidentialClientApplication } = require('@azure/msal-node')
const db = require('./db')
const cfg = require('./config')
const fs = require('fs')
const path = require('path')

const SCOPES = ['https://graph.microsoft.com/Mail.Read', 'https://graph.microsoft.com/Mail.ReadWrite', 'https://graph.microsoft.com/Mail.Send', 'offline_access']

const TEMP_DIR = process.env.DATA_DIR || process.env.TEMP_DIR || path.resolve(process.cwd(), cfg.server.data_dir || './data')
fs.mkdirSync(TEMP_DIR, { recursive: true })

function tokenCachePath(accountId) {
  return path.join(TEMP_DIR, `msal_${accountId || 'shared'}.json`)
}

function buildClient(accountId) {
  const cachePath = tokenCachePath(accountId)
  return new ConfidentialClientApplication({
    auth: {
      clientId: cfg.outlook.client_id,
      clientSecret: cfg.outlook.client_secret,
      authority: 'https://login.microsoftonline.com/common',
    },
    cache: {
      cachePlugin: {
        beforeCacheAccess: async (ctx) => {
          if (fs.existsSync(cachePath)) {
            ctx.tokenCache.deserialize(fs.readFileSync(cachePath, 'utf8'))
          }
        },
        afterCacheAccess: async (ctx) => {
          if (ctx.cacheHasChanged) {
            fs.writeFileSync(cachePath, ctx.tokenCache.serialize())
          }
        },
      },
    },
  })
}

async function getAuthUrl(redirectUri, state) {
  const params = { scopes: SCOPES, redirectUri }
  if (state) params.state = state
  return buildClient('shared').getAuthCodeUrl(params)
}

async function handleCallback(code, redirectUri) {
  const client = buildClient('shared')
  const result = await client.acquireTokenByCode({ code, scopes: SCOPES, redirectUri })
  return { result, email: result.account.username }
}

async function getAccessToken(accountId) {
  const client = buildClient(accountId)
  const accounts = await client.getTokenCache().getAllAccounts()
  if (!accounts.length) throw new Error('no cached account, re-auth required')
  const result = await client.acquireTokenSilent({ scopes: SCOPES, account: accounts[0] })
  return result.accessToken
}

module.exports = { getAuthUrl, handleCallback, getAccessToken }

