    })
  })
}

function fetchEmails(account, config) {
  return new Promise((resolve, reject) => {
    const imapCfg = IMAP_CONFIG[account.type]
    if (!imapCfg) return reject(new Error('unsupported type'))

    const imap = new Imap({
