router.get('/', (req, res) => {
  const { accountId, folder = 'inbox', page = 1 } = req.query
  const limit = 50
  const offset = (page - 1) * limit

  let rows
  if (folder === 'unread') {
    rows = accountId
      ? db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder FROM emails WHERE account_id = ? AND read = 0 AND deleted = 0 ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(accountId, limit, offset)
      : db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder FROM emails WHERE read = 0 AND deleted = 0 ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(limit, offset)
  } else if (folder === 'starred') {
    rows = accountId
      ? db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder FROM emails WHERE account_id = ? AND starred = 1 AND deleted = 0 ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(accountId, limit, offset)
      : db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder FROM emails WHERE starred = 1 AND deleted = 0 ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(limit, offset)
  } else if (accountId) {
    rows = db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder FROM emails WHERE account_id = ? AND folder = ? AND deleted = 0 ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(accountId, folder, limit, offset)
  } else {
    rows = db.prepare(`SELECT id, account_id, from_addr, from_name, subject, preview, date, read, starred, folder FROM emails WHERE folder = ? AND deleted = 0 ORDER BY raw_date DESC LIMIT ? OFFSET ?`).all(folder, limit, offset)
  }
  res.json(rows)
})

