{email.body && email.body.trim().startsWith('<') ? (
  <iframe
    srcDoc={email.body}
    sandbox="allow-same-origin allow-popups"
    className="w-full border-0"
    style={{ minHeight: 300 }}
    onLoad={e => {
      const f = e.currentTarget
      const update = () => {
        const h = f.contentDocument?.documentElement?.scrollHeight || f.contentDocument?.body?.scrollHeight || 300
        f.style.height = h + 'px'
      }
      update()
      // 图片等异步加载后重新计算高度
      const ro = new ResizeObserver(update)
      if (f.contentDocument?.body) ro.observe(f.contentDocument.body)
      f.contentWindow?.addEventListener('load', update)
    }}
  />
) : (
  <div className="text-sm text-gray-700 leading-relaxed whitespace-pre-wrap">{email.body}</div>
)}

