const loadAll = async () => {
  await fetchAccounts()
  if (savedPage > 1) {
    const pages = Array.from({ length: savedPage }, (_, i) => i + 1)
    const results = await Promise.all(pages.map(p =>
      fetch(`/api/emails?${new URLSearchParams({ ...(selectedAccountId && selectedAccountId !== 'all' ? { accountId: selectedAccountId } : {}), page: String(p) })}`, { credentials: 'include' })
        .then(r => r.json())
    ))
    const merged = results.flat().filter((e, i, arr) => arr.findIndex(x => x.id === e.id) === i)
    setEmails(merged.map(mapEmail))
