function fetchFolder(imap, account, imapFolder, folderKey) {
  return new Promise((resolve) => {
    imap.openBox(imapFolder, true, (err, box) => {
      if (err || !box || box.messages.total === 0) return resolve(0)
      const fetch = imap.seq.fetch('1:*', { bodies: '', struct: true })
      const promises = []
      fetch.on('message', (msg, seqno) => {
        let uid = seqno
        const p = new Promise(res => {
          msg.on('attributes', attrs => { uid = attrs.uid })
          msg.on('body', stream => {
            simpleParser(stream, (err, parsed) => {
              if (err) return res()
              const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, uid, folderKey)
              if (!existing) {
                const emailId = randomUUID()
                db.prepare(`INSERT INTO emails (id, account_id, uid, folder, from_addr, from_name, subject, preview, body, date, raw_date)
                  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
                  .run(
                    emailId, account.id, uid, folderKey,
                    parsed.from?.value?.[0]?.address || '',
                    parsed.from?.value?.[0]?.name || '',
                    parsed.subject || '(无主题)',
                    (parsed.text || '').slice(0, 100).replace(/\n/g, ' '),
                    parsed.html || parsed.text || '',
                    parsed.date ? parsed.date.toISOString() : new Date().toISOString(),
                    parsed.date ? parsed.date.getTime() : Date.now(),
                  )
                for (const att of (parsed.attachments || [])) {
                  if (!att.content) continue
                  if (att.content.length > 10 * 1024 * 1024) continue // 跳过超过 10MB 的附件
                  db.prepare('INSERT INTO attachments (id, email_id, filename, content_type, size, data) VALUES (?, ?, ?, ?, ?, ?)')
                    .run(randomUUID(), emailId, att.filename || 'attachment', att.contentType || 'application/octet-stream', att.size || att.content.length, att.content)
                }
              }
              res()
            })
          })
        })
        promises.push(p)

