const Imap = require('imap')
const { simpleParser } = require('mailparser')
const { convert } = require('html-to-text')
const db = require('./db')
const { randomUUID } = require('crypto')

function toPlainText(html, text) {
  if (text) return text.slice(0, 5000)
  if (html) return convert(html, { wordwrap: false, selectors: [{ selector: 'img', format: 'skip' }, { selector: 'a', options: { ignoreHref: true } }] }).slice(0, 5000)
  return ''
}

const IMAP_CONFIG = {
  gmail: { host: 'imap.gmail.com', port: 993, tls: true },
  qq:    { host: 'imap.qq.com',    port: 993, tls: true },
}

const FOLDER_MAP = {
  gmail:   { inbox: 'INBOX', sent: '[Gmail]/已发邮件', draft: '[Gmail]/草稿', trash: '[Gmail]/已删除邮件', spam: '[Gmail]/垃圾邮件' },
  qq:      { inbox: 'INBOX', sent: 'Sent Messages',   draft: 'Drafts',       trash: 'Deleted Messages', spam: 'Junk' },
}

// QQ 邮箱文件夹名备选（不同版本可能不同）
const QQ_FOLDER_FALLBACK = {
  sent:  ['Sent Messages', '已发送', 'Sent'],
  draft: ['Drafts', '草稿箱', '草稿'],
  trash: ['Deleted Messages', '已删除', 'Trash'],
  spam:  ['Junk', '垃圾', 'Spam'],
}

function fetchFolder(imap, account, imapFolder, folderKey) {
  return new Promise((resolve) => {
    imap.openBox(imapFolder, true, (err, box) => {
      if (err || !box || box.messages.total === 0) return resolve(0)
      const fetch = imap.seq.fetch('1:*', { bodies: '', struct: true })
      const promises = []
      const rows = [] // 收集待写入数据
      fetch.on('message', (msg, seqno) => {
        let uid = seqno
        const p = new Promise(res => {
          msg.on('attributes', attrs => { uid = attrs.uid })
          msg.on('body', stream => {
            simpleParser(stream, (err, parsed) => {
              if (err) return res()
              const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, uid, folderKey)
              if (!existing) {
                rows.push({ uid, folderKey, parsed })
              }
              res()
            })
          })
        })
        promises.push(p)
      })
      fetch.once('end', async () => {
        await Promise.all(promises)
        // 批量事务写入
        const insertEmail = db.prepare(`INSERT INTO emails (id, account_id, uid, folder, from_addr, from_name, subject, preview, body, date, raw_date) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        const insertAtt = db.prepare('INSERT INTO attachments (id, email_id, filename, content_type, size, data) VALUES (?, ?, ?, ?, ?, ?)')
        db.transaction(() => {
          for (const { uid, folderKey: fk, parsed } of rows) {
            const emailId = randomUUID()
            insertEmail.run(emailId, account.id, uid, fk,
              parsed.from?.value?.[0]?.address || '',
              parsed.from?.value?.[0]?.name || '',
              parsed.subject || '(无主题)',
              (parsed.text || '').slice(0, 100).replace(/\n/g, ' '),
              parsed.html || parsed.text || '',
              parsed.date ? parsed.date.toISOString() : new Date().toISOString(),
              parsed.date ? parsed.date.getTime() : Date.now(),
            )
            for (const att of (parsed.attachments || [])) {
              if (!att.content || att.content.length > 10 * 1024 * 1024) continue
              insertAtt.run(randomUUID(), emailId, att.filename || 'attachment', att.contentType || 'application/octet-stream', att.size || att.content.length, att.content)
            }
          }
        })()
        resolve(rows.length)
      })
      fetch.once('error', () => resolve(0))
    })
  })
}

function fetchEmails(account, config) {
  return new Promise((resolve, reject) => {
    const imapCfg = IMAP_CONFIG[account.type]
    if (!imapCfg) return reject(new Error('unsupported type'))

    const imap = new Imap({
      user: account.email,
      password: config.credential,
      ...imapCfg,
      tlsOptions: { rejectUnauthorized: false },
      connTimeout: 15000,
      authTimeout: 10000,
    })

    imap.once('ready', async () => {
      const folders = FOLDER_MAP[account.type] || FOLDER_MAP.qq
      let total = 0
      for (const [folderKey, imapFolder] of Object.entries(folders)) {
        const candidates = (account.type === 'qq' && QQ_FOLDER_FALLBACK[folderKey])
          ? QQ_FOLDER_FALLBACK[folderKey]
          : [imapFolder]
        for (const candidate of candidates) {
          try {
            const n = await fetchFolder(imap, account, candidate, folderKey)
            total += n
            break // 成功则不再尝试下一个
          } catch (e) {
            // try next candidate
          }
        }
      }
      imap.end()
      resolve(total)
    })

    imap.once('error', reject)
    imap.connect()
  })
}

module.exports = { fetchEmails }

