router.get('/:id/attachments', (req, res) => {
  const rows = db.prepare('SELECT id, filename, content_type, size FROM attachments WHERE email_id = ?').all(req.params.id)
  res.json(rows)
})

// GET /api/emails/:id/attachments/:attId
router.get('/:id/attachments/:attId', (req, res) => {
  const att = db.prepare('SELECT filename, content_type, data FROM attachments WHERE id = ? AND email_id = ?').get(req.params.attId, req.params.id)
  if (!att) return res.status(404).json({ error: 'not found' })
  res.setHeader('Content-Disposition', `attachment; filename="${encodeURIComponent(att.filename)}"`)
  res.setHeader('Content-Type', att.content_type || 'application/octet-stream')
  res.send(att.data)
})

// POST /api/emails/sync/:accountId
router.post('/sync/:accountId', async (req, res) => {
  const account = accountsDb.prepare('SELECT * FROM accounts WHERE id = ?').get(req.params.accountId)
  if (!account) return res.status(404).json({ error: 'account not found' })

  const config = JSON.parse(account.config)

  if (account.type === 'outlook') {
    let token
    try { token = await getAccessToken(account.id) }
    catch (e) { return res.status(401).json({ error: 'token_expired', message: '授权已过期，请重新添加账号' }) }
    const nodeFetch = (await import('node-fetch')).default
    const OUTLOOK_FOLDERS = {
      inbox: 'inbox',
      sent: 'sentitems',
      draft: 'drafts',
      trash: 'deleteditems',
      spam: 'junkemail',
    }
    let count = 0
    for (const [folderKey, folderId] of Object.entries(OUTLOOK_FOLDERS)) {
      let url = `https://graph.microsoft.com/v1.0/me/mailFolders/${folderId}/messages?$top=999&$orderby=receivedDateTime desc&$select=id,subject,from,bodyPreview,body,receivedDateTime,isRead,hasAttachments`
      let pageCount = 0
      while (url && pageCount < 20) {
        pageCount++
        const resp = await nodeFetch(url, { headers: { Authorization: `Bearer ${token}` } })
        const data = await resp.json()
        const attTasks = []
        for (const msg of (data.value || [])) {
          const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ?').get(account.id, msg.id)
          if (!existing) {
            const emailId = randomUUID()
            db.prepare(`INSERT INTO emails (id, account_id, uid, folder, from_addr, from_name, subject, preview, body, date, read, raw_date)
              VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
              .run(emailId, account.id, msg.id, folderKey,
                msg.from?.emailAddress?.address || '',
                msg.from?.emailAddress?.name || '',
                msg.subject || '(无主题)',
                (msg.bodyPreview || '').slice(0, 100),
                msg.body?.content || '',
                msg.receivedDateTime || new Date().toISOString(),
                msg.isRead ? 1 : 0,
                msg.receivedDateTime ? new Date(msg.receivedDateTime).getTime() : Date.now(),
              )
            if (msg.hasAttachments) {
              attTasks.push(
                nodeFetch(`https://graph.microsoft.com/v1.0/me/messages/${msg.id}/attachments`, { headers: { Authorization: `Bearer ${token}` } })
                  .then(r => r.json())
                  .then(attData => {
                    for (const att of (attData.value || [])) {
                      if (att['@odata.type'] !== '#microsoft.graph.fileAttachment') continue
                      const buf = Buffer.from(att.contentBytes || '', 'base64')
                      if (buf.length > 10 * 1024 * 1024) continue
                      db.prepare('INSERT INTO attachments (id, email_id, filename, content_type, size, data) VALUES (?, ?, ?, ?, ?, ?)')
                        .run(randomUUID(), emailId, att.name || 'attachment', att.contentType || 'application/octet-stream', buf.length, buf)
                    }
                  })
                  .catch(() => {})
              )
            }
            count++
          }
        }
        await Promise.all(attTasks)
        url = data['@odata.nextLink'] || null
      }
    }
    const oneMonthAgo = Date.now() - 30 * 24 * 60 * 60 * 1000
    db.prepare('UPDATE emails SET read = 1 WHERE account_id = ? AND read = 0 AND (raw_date < ? OR raw_date = 0) AND deleted = 0')
      .run(account.id, oneMonthAgo)
    return res.json({ synced: count })
  }
  // 标记超过一个月的邮件为已读
  const oneMonthAgo = Date.now() - 30 * 24 * 60 * 60 * 1000
  try {
    const count = await fetchEmails(account, config)
    db.prepare('UPDATE emails SET read = 1 WHERE account_id = ? AND read = 0 AND (raw_date < ? OR raw_date = 0) AND deleted = 0')
      .run(account.id, oneMonthAgo)
    res.json({ synced: count })
  } catch (e) {
    res.status(500).json({ error: 'sync_failed', message: e.message })
  }
})

// Outlook OAuth2 flow
router.get('/oauth/outlook', async (req, res) => {
  const redirectUri = process.env.OUTLOOK_REDIRECT_URI || `${req.protocol}://${req.get('host')}/api/emails/oauth/outlook/callback`
  const url = await getAuthUrl(redirectUri)
  res.redirect(url)
})

router.get('/oauth/outlook/callback', async (req, res) => {
  const { code, error, error_description } = req.query
  if (error) {
    return res.redirect(`/?oauth=error&reason=${encodeURIComponent(error_description || error)}`)
  }
  const redirectUri = process.env.OUTLOOK_REDIRECT_URI || `${req.protocol}://${req.get('host')}/api/emails/oauth/outlook/callback`
  const result = await handleCallback(code, redirectUri)

  const email = result.account.username
  const existing = accountsDb.prepare('SELECT id FROM accounts WHERE email = ?').get(email)
  if (!existing) {
    const count = accountsDb.prepare('SELECT COUNT(*) as n FROM accounts').get().n
    const COLORS = ['#4A90D9','#E91E8C','#FF7043','#8BC34A','#9C27B0','#26A69A','#FF9800','#607D8B']
    accountsDb.prepare('INSERT INTO accounts (id, email, type, color, config) VALUES (?, ?, ?, ?, ?)')
      .run(randomUUID(), email, 'outlook', COLORS[count % COLORS.length],
        JSON.stringify({ refreshToken: result.account.homeAccountId }))
  }

  res.redirect('/?oauth=success')
})

module.exports = router

const Database = require('better-sqlite3')
const path = require('path')
const fs = require('fs')
const cfg = require('./config')

const DATA_DIR = process.env.DATA_DIR || (
  path.isAbsolute(cfg.server.data_dir)
    ? cfg.server.data_dir
    : path.resolve(process.cwd(), cfg.server.data_dir)
)
fs.mkdirSync(DATA_DIR, { recursive: true })

const db = new Database(path.join(DATA_DIR, 'imall.db'))

db.exec(`
  CREATE TABLE IF NOT EXISTS accounts (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    type TEXT NOT NULL,
    color TEXT NOT NULL,
    config TEXT NOT NULL,
    created_at INTEGER DEFAULT (unixepoch())
  );

  CREATE TABLE IF NOT EXISTS emails (
    id TEXT PRIMARY KEY,
    account_id TEXT NOT NULL,
    uid INTEGER,
    folder TEXT DEFAULT 'inbox',
    from_addr TEXT,
    from_name TEXT,
    subject TEXT,
    preview TEXT,
    body TEXT,
    date TEXT,
    read INTEGER DEFAULT 0,
    starred INTEGER DEFAULT 0,
    deleted INTEGER DEFAULT 0,
    raw_date INTEGER
  );

  CREATE INDEX IF NOT EXISTS idx_emails_account ON emails(account_id, folder, deleted);
  CREATE INDEX IF NOT EXISTS idx_emails_folder_date ON emails(folder, raw_date DESC);
  CREATE INDEX IF NOT EXISTS idx_emails_account_folder_date ON emails(account_id, folder, raw_date DESC);

  CREATE TABLE IF NOT EXISTS settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS attachments (
    id TEXT PRIMARY KEY,
    email_id TEXT NOT NULL,
    filename TEXT NOT NULL,
    content_type TEXT,
    size INTEGER,
    data BLOB
  );
`)

module.exports = db

// ── 数据迁移（每次启动自动执行，幂等）──────────────────────────────
// 1. 修复 raw_date=0 的旧邮件：尝试从 date 字段解析时间戳
const migrated = db.prepare("SELECT value FROM settings WHERE key = 'migration_raw_date_fixed'").get()
if (!migrated) {
  const zeroDateRows = db.prepare("SELECT id, date FROM emails WHERE raw_date = 0 OR raw_date IS NULL").all()
  if (zeroDateRows.length > 0) {
    const upd = db.prepare("UPDATE emails SET raw_date = ? WHERE id = ?")
    db.transaction(() => {
      for (const row of zeroDateRows) {
        const ts = row.date ? new Date(row.date).getTime() : null
        if (ts && !isNaN(ts)) upd.run(ts, row.id)
      }
    })()
    console.log(`[db] 修复 ${zeroDateRows.length} 封邮件的 raw_date`)
  }
  db.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('migration_raw_date_fixed', '1')").run()
}

// 2. 修复 folder 为空的旧邮件，默认归入 inbox
const folderMigrated = db.prepare("SELECT value FROM settings WHERE key = 'migration_folder_fixed'").get()
if (!folderMigrated) {
  const { changes: folderFix } = db.prepare("UPDATE emails SET folder = 'inbox' WHERE folder IS NULL OR folder = ''").run()
  if (folderFix > 0) console.log(`[db] 修复 ${folderFix} 封邮件的 folder 字段`)
  db.prepare("INSERT OR REPLACE INTO settings (key, value) VALUES ('migration_folder_fixed', '1')").run()
}

// Auto-import accounts.db if present (migration helper)
const importPath = path.join(DATA_DIR, 'accounts.db')
if (fs.existsSync(importPath)) {
  try {
    db.exec(`
      ATTACH '${importPath.replace(/'/g, "''")}' AS migration;
      INSERT OR IGNORE INTO accounts SELECT * FROM migration.accounts;
      DETACH migration;
    `)
    fs.renameSync(importPath, importPath + '.imported')
    console.log('[db] accounts.db imported and renamed to accounts.db.imported')
  } catch (e) {
    console.error('[db] import failed:', e.message)
  }
}

