          <div className="relative flex-1">
            <select
              value={fromId}
              onChange={e => setFromId(e.target.value)}
              className="w-full text-sm text-gray-800 bg-transparent appearance-none pr-6 focus:outline-none"
            >
              {accounts.map(a => (
                <option key={a.id} value={a.id}>{a.email}</option>
              ))}
            </select>
            <ChevronDown size={14} className="absolute right-0 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
          </div>
        </div>

        {/* To */}
        <div className="flex items-center gap-2 px-4 py-2.5 border-b border-gray-100">
          <span className="text-xs text-gray-400 w-10 flex-shrink-0">收件人</span>
          <input
            type="text" value={to} onChange={e => setTo(e.target.value)}
            placeholder="example@email.com"
            className="flex-1 text-sm text-gray-800 focus:outline-none"
          />
        </div>

        {/* BCC */}
        <div className="flex items-center gap-2 px-4 py-2.5 border-b border-gray-100">
          <span className="text-xs text-gray-400 w-10 flex-shrink-0">密送</span>
          <input
            type="text" value={bcc} onChange={e => setBcc(e.target.value)}
            placeholder="example@email.com"
            className="flex-1 text-sm text-gray-800 focus:outline-none"
          />
        </div>

        {/* Subject */}
        <div className="flex items-center gap-2 px-4 py-2.5 border-b border-gray-100">
          <span className="text-xs text-gray-400 w-10 flex-shrink-0">主题</span>
          <input
            type="text" value={subject} onChange={e => setSubject(e.target.value)}
            placeholder="邮件主题"
            className="flex-1 text-sm text-gray-800 focus:outline-none"
          />
        </div>
      </div>

      {/* Body */}
      <textarea
        value={replyText} onChange={e => setReplyText(e.target.value)}
        placeholder="正文..."
        className="w-full px-4 py-3 text-sm text-gray-800 focus:outline-none resize-none"
        style={{ minHeight: isReply ? 120 : undefined, flex: isReply ? '0 0 auto' : 1 }}
      />
      {isReply && initial.body && (
        <div className="flex-1 overflow-y-auto px-4 py-2 border-t border-gray-100 text-sm text-gray-500"
          dangerouslySetInnerHTML={{ __html: initial.body }} />
      )}

      {/* Footer */}
      <div className="px-4 py-3 border-t border-gray-100 flex items-center justify-between">
        {error ? <span className="text-xs text-red-500">{error}</span> : <span />}
        <button
          onClick={handleSend} disabled={sending || !fromId}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium disabled:opacity-50"
        >
          <Send size={15} />
          {sending ? '发送中...' : '发送'}
        </button>
      </div>
    </div>
  )
}

import { ArrowLeft, Trash2, Star, MailOpen, MailCheck, Reply, Pencil } from 'lucide-react'
import { useState, useEffect, useCallback } from 'react'
import type { Email, Account } from '../types'
import { getInitials } from '../data'
import Avatar from './Avatar'
import { Paperclip, Download } from 'lucide-react'

interface Attachment { id: string; filename: string; content_type: string; size: number }

interface Props {
  email: Email
  account?: Account
  onBack: () => void
  onDelete: () => void
  onStar: () => void
  onMarkRead: (read: boolean) => void
  onReply: () => void
  onRefresh?: () => void
  onEdit?: () => void
}

export default function EmailDetail({ email, account, onBack, onDelete, onStar, onMarkRead, onReply, onRefresh, onEdit }: Props) {
  const [attachments, setAttachments] = useState<Attachment[]>([])

  const loadAttachments = useCallback(() => {
    fetch(`/api/emails/${email.id}/attachments`, { credentials: 'include' })
      .then(r => r.json())
      .then(data => setAttachments(Array.isArray(data) ? data : []))
      .catch(() => {})
  }, [email.id])

  useEffect(() => { loadAttachments() }, [loadAttachments])
  return (
    <div className="flex flex-col h-full bg-white">
      <div className="flex items-center border-b border-gray-100">
        {/* 左侧大区域点击返回 */}
        <div className="flex-1 flex items-center gap-2 px-4 py-3 cursor-pointer hover:bg-gray-50" onClick={onBack}>
          <ArrowLeft size={22} className="text-gray-600 flex-shrink-0" />
          <span className="text-sm text-gray-500 truncate">{email.subject}</span>
        </div>
        {/* 右侧操作按钮 */}
        <div className="flex items-center gap-1 px-3 py-3">
          <button onClick={onDelete}><Trash2 size={20} className="text-gray-600 hover:text-red-500" /></button>
          {email.folder === 'draft' ? (
            <button onClick={onEdit} title="继续编辑"><Pencil size={20} className="text-gray-500 hover:text-blue-500" /></button>
          ) : (
            <button onClick={onReply} title="回复"><Reply size={20} className="text-gray-500 hover:text-blue-500" /></button>
          )}
          <button onClick={() => onMarkRead(!email.read)} title={email.read ? '标为未读' : '标为已读'}>
            {email.read
              ? <MailCheck size={20} className="text-gray-500 hover:text-blue-500" />
              : <MailOpen size={20} className="text-gray-500 hover:text-blue-500" />}
          </button>
          {onRefresh && null}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-4">
        {account && (
          <div className="inline-block px-3 py-1 rounded-full text-white text-xs mb-3" style={{ background: account.color }}>
            {account.email}
          </div>
        )}

        <div className="flex items-start justify-between gap-2 mb-4">
          <h1 className="text-lg font-semibold text-gray-900 leading-snug">{email.subject}</h1>
          <button onClick={onStar} className="flex-shrink-0 mt-1">
            <Star size={20} className={email.starred ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'} />
          </button>
        </div>

        <div className="flex items-center gap-3 mb-4">
          <Avatar text={getInitials(email.fromName || email.from)} color={account?.color || '#888'} />
          <div>
            <div className="font-semibold text-sm text-gray-900">{email.fromName}</div>
            <div className="text-xs text-gray-500">到 我</div>
          </div>
          <span className="text-xs text-blue-500 ml-1">{email.date}</span>
        </div>

        {email.body && email.body.trim().startsWith('<') ? (
          <iframe
            srcDoc={email.body}
            sandbox="allow-popups allow-scripts"
            className="w-full border-0"
            style={{ minHeight: 300 }}
            onLoad={e => {
              const f = e.currentTarget
              const update = () => {
                const h = f.contentDocument?.documentElement?.scrollHeight || f.contentDocument?.body?.scrollHeight || 300
                f.style.height = h + 'px'
              }
              update()
              // 图片等异步加载后重新计算高度
              const ro = new ResizeObserver(update)
              if (f.contentDocument?.body) ro.observe(f.contentDocument.body)
              f.contentWindow?.addEventListener('load', update)
            }}
          />
        ) : (
          <div className="text-sm text-gray-700 leading-relaxed whitespace-pre-wrap">{email.body}</div>
        )}

        {attachments.length > 0 && (
          <div className="mt-4 pt-4 border-t border-gray-100">
            <div className="flex items-center gap-1 text-xs text-gray-500 mb-2">
              <Paperclip size={13} />
              <span>{attachments.length} 个附件</span>
            </div>
            <div className="flex flex-wrap gap-2">
              {attachments.map(att => (
                <a
                  key={att.id}
                  href={`/api/emails/${email.id}/attachments/${att.id}`}
                  download={att.filename}
                  className="flex items-center gap-1.5 px-3 py-1.5 bg-gray-50 border border-gray-200 rounded-lg text-xs text-gray-700 hover:bg-gray-100"
                >
                  <Download size={12} className="text-gray-400" />
                  <span className="max-w-[160px] truncate">{att.filename}</span>
                  <span className="text-gray-400">({Math.round(att.size / 1024)}KB)</span>
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

