export default function Drawer({ accounts, selectedAccountId, onSelectAccount, onAddAccount, onSettings, onSync, onClose, syncing }: Props) {
  const { accountId: selAccountId } = parseFolderId(selectedAccountId)
  const [invalidAccounts, setInvalidAccounts] = useState<{ id: string; email: string }[]>([])

  const checkStatus = () => {
    fetch('/api/accounts/status', { credentials: 'include' })
      .then(r => r.json())
      .then(data => {
        setInvalidAccounts(Array.isArray(data) ? data.filter((a: { valid: boolean }) => !a.valid) : [])
        localStorage.setItem('imail_last_status_check', String(Date.now()))
      })
      .catch(() => {})
  }

  useEffect(() => {
    // 初次加载或每天自动检测
    const last = parseInt(localStorage.getItem('imail_last_status_check') || '0')
    if (Date.now() - last > 24 * 60 * 60 * 1000) checkStatus()
  }, [])

  // accounts 数量变化时也刷新（添加/删除账号）
  useEffect(() => { checkStatus() }, [accounts.length])

