function purgeOldEmails() {
  const db = require('./db')
  const oneYearAgo = Date.now() - 365 * 24 * 60 * 60 * 1000
  const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000
  // 记录将被清理的 uid，防止重新同步
  const toDelete = db.prepare('SELECT account_id, uid, folder FROM emails WHERE starred = 0 AND raw_date > 0 AND raw_date < ? AND deleted = 0').all(oneYearAgo)
  if (toDelete.length > 0) {
    const insertUid = db.prepare('INSERT OR IGNORE INTO deleted_uids (account_id, uid, folder) VALUES (?, ?, ?)')
    db.transaction(() => { for (const r of toDelete) insertUid.run(r.account_id, String(r.uid), r.folder) })()
    const { changes } = db.prepare('DELETE FROM emails WHERE starred = 0 AND raw_date > 0 AND raw_date < ? AND deleted = 0').run(oneYearAgo)
    console.log(`[purge] 清理 ${changes} 封超1年邮件`)
  }
  // 清理软删除超30天的邮件
  const { changes: dc } = db.prepare('DELETE FROM emails WHERE deleted = 1 AND raw_date > 0 AND raw_date < ?').run(thirtyDaysAgo)
  if (dc > 0) console.log(`[purge] 清理 ${dc} 封软删除邮件`)
  // 清理孤立附件
  const { changes: ac } = db.prepare('DELETE FROM attachments WHERE email_id NOT IN (SELECT id FROM emails)').run()
  if (ac > 0) console.log(`[purge] 清理 ${ac} 个孤立附件`)
  // 清理所有附件 BLOB 数据（只保留元数据）
  const { changes: bc } = db.prepare('UPDATE attachments SET data = NULL WHERE data IS NOT NULL').run()

