const db=require('better-sqlite3')('/app/data/imall.db');
const r=db.prepare('SELECT id,subject,body FROM emails ORDER BY raw_date DESC LIMIT 1').get();
console.log('subject:',r.subject);
console.log('body前100:',r.body?.slice(0,100));
console.log('是否HTML:',r.body?.includes('<'));
"
```

