function fetchFolder(imap, account, imapFolder, folderKey) {
  return new Promise((resolve) => {
    imap.openBox(imapFolder, true, (err, box) => {
      if (err || !box || box.messages.total === 0) return resolve(0)
      const total = box.messages.total
      const range = `1:${total}`
      const imapFetch = imap.seq.fetch(range, { bodies: '', struct: true })
      const promises = []
      const rows = []
      imapFetch.on('message', (msg, _seqno) => {
        let uid = null
        let flags = []
        let uidResolve
        const uidReady = Promise.race([
          new Promise(r => { uidResolve = r }),
          new Promise(r => setTimeout(r, 3000)),
        ])
        const p = new Promise(res => {
          msg.on('attributes', attrs => { uid = attrs.uid; flags = attrs.flags || []; uidResolve && uidResolve() })
          msg.on('body', stream => {
            simpleParser(stream, { Iconv }, async (err, parsed) => {
              if (err) return res()
              await uidReady
              if (!uid) return res() // attributes 超时，跳过
              const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, uid, folderKey)
              const purged = db.prepare('SELECT 1 FROM deleted_uids WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, String(uid), folderKey)
              if (!existing && !purged) rows.push({ uid, folderKey, parsed, flags })
              res()
            })
          })
        })
        promises.push(p)
      })
      imapFetch.once('end', async () => {
        await Promise.all(promises)
        // 批量事务写入
        const insertEmail = db.prepare(`INSERT INTO emails (id, account_id, uid, folder, from_addr, from_name, subject, preview, body, date, raw_date, read) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        const insertAtt = db.prepare('INSERT INTO attachments (id, email_id, filename, content_type, size) VALUES (?, ?, ?, ?, ?)')
        const threeMonthsAgo = Date.now() - 90 * 24 * 60 * 60 * 1000
        db.transaction(() => {
          for (const { uid, folderKey: fk, parsed, flags } of rows) {
            const emailId = randomUUID()
            const emailDate = parsed.date ? parsed.date.getTime() : Date.now()
            const isOld = emailDate < threeMonthsAgo
            // 超3月：body置空标已读；3月内：存完整body按服务器read状态
            const body = isOld ? '' : (parsed.html || parsed.text || '')
            const read = isOld ? 1 : (flags.includes('\\Seen') ? 1 : 0)
            insertEmail.run(emailId, account.id, uid, fk,
              parsed.from?.value?.[0]?.address || '',
              parsed.from?.value?.[0]?.name || '',
              parsed.subject || '(无主题)',
              (parsed.text || '').slice(0, 100).replace(/\n/g, ' '),
              body,
              parsed.date ? parsed.date.toISOString() : new Date().toISOString(),
              emailDate,
              read,
            )
            if (!isOld) {
              for (const att of (parsed.attachments || [])) {
                if (!att.filename) continue
                insertAtt.run(randomUUID(), emailId, att.filename, att.contentType || 'application/octet-stream', att.size || att.content?.length || 0)
              }
            }
          }
        })()
        resolve(rows.length)
      })
      imapFetch.once('error', () => resolve(0))
    })
  })

