    imap.openBox(imapFolder, true, (err, box) => {
      if (err || !box || box.messages.total === 0) return resolve(0)
      const total = box.messages.total
      const threeMonthsAgo = Date.now() - 90 * 24 * 60 * 60 * 1000
      // 第一阶段：全量拉 header（快）
      const headerFetch = imap.seq.fetch(`1:${total}`, { bodies: 'HEADER', struct: false })
      const headerRows = []
      const headerPromises = []
      headerFetch.on('message', (msg) => {
        let uid = null, flags = []
        let uidResolve
        const uidReady = Promise.race([new Promise(r => { uidResolve = r }), new Promise(r => setTimeout(r, 3000))])
        const p = new Promise(res => {
          msg.on('attributes', attrs => { uid = attrs.uid; flags = attrs.flags || []; uidResolve && uidResolve() })
          msg.on('body', stream => {
            simpleParser(stream, { Iconv }, async (err, parsed) => {
              if (err) return res()
              await uidReady
              if (!uid) return res()
              const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, uid, folderKey)
              const purged = db.prepare('SELECT 1 FROM deleted_uids WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, String(uid), folderKey)
              if (!existing && !purged) headerRows.push({ uid, flags, parsed })
              res()
            })
          })
        })
        headerPromises.push(p)
      })
      headerFetch.once('error', () => resolve(0))
      headerFetch.once('end', async () => {
        await Promise.all(headerPromises)
        if (headerRows.length === 0) return resolve(0)
        // 分组：超3月直接存列表，3月内需要补 body
        const oldRows = headerRows.filter(r => (r.parsed.date?.getTime() || 0) < threeMonthsAgo)
        const newUids = headerRows.filter(r => (r.parsed.date?.getTime() || 0) >= threeMonthsAgo).map(r => r.uid)
        // 第二阶段：对3月内的补拉完整 body
        const bodyMap = new Map()
        await new Promise(res2 => {
          if (newUids.length === 0) return res2()
          const bodyFetch = imap.fetch(newUids, { bodies: '', struct: true })
          const bp = []
          bodyFetch.on('message', msg => {
            let uid2 = null
            let uidRes2
            const uidReady2 = Promise.race([new Promise(r => { uidRes2 = r }), new Promise(r => setTimeout(r, 3000))])
            const p2 = new Promise(r2 => {
              msg.on('attributes', attrs => { uid2 = attrs.uid; uidRes2 && uidRes2() })
              msg.on('body', stream => {
                simpleParser(stream, { Iconv }, async (err, parsed) => {
                  if (err) return r2()
                  await uidReady2
                  if (uid2) bodyMap.set(uid2, parsed)
                  r2()
                })
              })
            })
            bp.push(p2)
          })
          bodyFetch.once('end', async () => { await Promise.all(bp); res2() })
          bodyFetch.once('error', () => res2())
        })
        // 写入 db
        const insertEmail = db.prepare(`INSERT INTO emails (id, account_id, uid, folder, from_addr, from_name, subject, preview, body, date, raw_date, read) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        const insertAtt = db.prepare('INSERT INTO attachments (id, email_id, filename, content_type, size) VALUES (?, ?, ?, ?, ?)')
        db.transaction(() => {
          for (const { uid, flags, parsed: hp } of oldRows) {
            const emailDate = hp.date?.getTime() || Date.now()
            insertEmail.run(randomUUID(), account.id, uid, folderKey,
              hp.from?.value?.[0]?.address || '', hp.from?.value?.[0]?.name || '',
              hp.subject || '(无主题)', '', '', hp.date?.toISOString() || new Date().toISOString(), emailDate, 1)
          }
          for (const { uid, flags } of headerRows.filter(r => (r.parsed.date?.getTime() || 0) >= threeMonthsAgo)) {
            const fp = bodyMap.get(uid) || headerRows.find(r => r.uid === uid)?.parsed
            if (!fp) continue
            const emailDate = fp.date?.getTime() || Date.now()
            const emailId = randomUUID()
            const body = fp.html || fp.text || ''
            const read = flags.includes('\\Seen') ? 1 : 0
            insertEmail.run(emailId, account.id, uid, folderKey,
              fp.from?.value?.[0]?.address || '', fp.from?.value?.[0]?.name || '',
              fp.subject || '(无主题)', (fp.text || '').slice(0, 100).replace(/\n/g, ' '),
              body, fp.date?.toISOString() || new Date().toISOString(), emailDate, read)
            for (const att of (fp.attachments || [])) {
              if (!att.filename) continue
              insertAtt.run(randomUUID(), emailId, att.filename, att.contentType || 'application/octet-stream', att.size || att.content?.length || 0)
            }
          }
        })()
        resolve(headerRows.length)
      })
    })
  })

