const BATCH = 500
const headerRows = []
// 分批拉取 header，每批 500 封，避免大邮箱断连
for (let start = 1; start <= total; start += BATCH) {
  const end = Math.min(start + BATCH - 1, total)
  await new Promise(res => {
    const headerFetch = imap.seq.fetch(`${start}:${end}`, { bodies: 'HEADER', struct: false })
    const batchPromises = []
    headerFetch.on('message', (msg) => {
      let uid = null, flags = []
      let uidResolve
      const uidReady = Promise.race([new Promise(r => { uidResolve = r }), new Promise(r => setTimeout(r, 3000))])
      const p = new Promise(r2 => {
        msg.on('attributes', attrs => { uid = attrs.uid; flags = attrs.flags || []; uidResolve && uidResolve() })
        msg.on('body', stream => {
          simpleParser(stream, { Iconv }, async (err, parsed) => {
            if (err) return r2()
            await uidReady
            if (!uid) return r2()
            const existing = db.prepare('SELECT id FROM emails WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, uid, folderKey)
            const purged = db.prepare('SELECT 1 FROM deleted_uids WHERE account_id = ? AND uid = ? AND folder = ?').get(account.id, String(uid), folderKey)
            if (!existing && !purged) headerRows.push({ uid, flags, parsed })
            r2()
          })
        })
      })
      batchPromises.push(p)
    })
    headerFetch.once('error', (e) => { console.log(`[fetchFolder] batch error:`, e.message); res() })
    headerFetch.once('end', async () => { await Promise.all(batchPromises); res() })
  })
}
