两个问题：

1. **右栏日期 `2026/04/11 20:48`** — 这是今天同步进来的邮件，但真实发送时间应该是 2023 年（发票邮件）。说明 internalDate 修复还没生效，或者这封邮件的 internalDate 本身就是今天（QQ 邮箱服务器内部日期）
2. **中栏大量重复邮件**（红框内，QQ邮箱管理员同一时间多封）— unique 索引还没在 VPS 上生效

先确认 VPS 是否有 unique 索引：

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
console.log(db.prepare(\"SELECT name FROM sqlite_master WHERE type='index' AND name='idx_emails_uid_unique'\").get());
const id=db.prepare('SELECT id FROM accounts').all().find(r=>r.id.startsWith('ca250226')).id;
// 查这封发票邮件的真实日期
const r=db.prepare(\"SELECT uid,date,raw_date FROM emails WHERE account_id=? AND subject LIKE '%增值税%' LIMIT 3\").all(id);
r.forEach(x=>console.log('uid:',x.uid,'date:',x.date,'raw:',new Date(x.raw_date).toISOString()));
"
```

unique 索引有了 ✅。但发票邮件 date 是今天，说明 QQ 邮箱服务器的 `internalDate` 本身就是今天（可能是邮件被重新投递或迁移导致）。

真实发送时间只能从邮件 header 的 `Date` 字段获取。但之前测试 `bodies: 'HEADER'` 时 `parsed.date` 是 undefined。

用完整 body 拉取时 date 是否正确：

```bash
docker exec iMail node -e "
const Imap=require('imap');
const {simpleParser}=require('mailparser');
const Iconv=require('iconv').Iconv;
const db=require('better-sqlite3')('/app/data/imall.db');
const acc=db.prepare(\"SELECT * FROM accounts WHERE email='824559662@qq.com'\").get();
const cfg=JSON.parse(acc.config);
const imap=new Imap({user:acc.email,password:cfg.credential,host:'imap.qq.com',port:993,tls:true,tlsOptions:{rejectUnauthorized:false},connTimeout:15000});
imap.once('ready',()=>{
  imap.openBox('INBOX',true,()=>{
    imap.search([['UID','35697:35697']],(err,seqs)=>{
      const f=imap.fetch(seqs,{bodies:'',struct:false});
      f.on('message',(msg,seqno)=>{
        msg.on('attributes',attrs=>console.log('internalDate:',attrs.date));
        msg.on('body',stream=>{
          simpleParser(stream,{Iconv},(err,parsed)=>{
            console.log('parsed.date:',parsed?.date);
          });
        });
      });
      f.once('end',()=>imap.end());
    });
  });
});
imap.connect();
"
```

