async function getAuthUrl(redirectUri, state, loginHint) {
  const params = new URLSearchParams({
    client_id: cfg.outlook.client_id,
    response_type: 'code',
    redirect_uri: redirectUri,
    scope: SCOPES.join(' ') + ' openid profile',
    response_mode: 'query',
