  const email = result.email
  // 复制 msal_tmp_xxx.json -> msal_email.json
  const accountPath = path.join(DATA_DIR, `msal_${email}.json`)
  if (result.tmpCachePath && fs.existsSync(result.tmpCachePath)) {
    fs.copyFileSync(result.tmpCachePath, accountPath)
    fs.unlinkSync(result.tmpCachePath)
  }
  // 从 cache 文件读取 homeAccountId 写入 config
  const cache = JSON.parse(fs.readFileSync(accountPath, 'utf8'))
  const match = Object.values(cache.Account || {}).find(a => a.username?.toLowerCase() === email.toLowerCase())
  const homeId = match?.home_account_id || ''
  if (homeId) accountsDb.prepare('UPDATE accounts SET config=? WHERE id=?').run(JSON.stringify({ refreshToken: homeId }), accountId)
})
```

## 需要备份的文件
- `data/imall.db` — 账号、邮件、设置
- `data/msal_*.json` — 每个 Outlook 账号的 token（以邮箱命名）
- 不需要备份 `data/sessions/`（登录状态，重新登录即可）

## 串号问题排查
如果账号显示别人的邮件，检查：
1. `data/msal_email.json` 里是否混有多个账号的 token
2. db 里 `config.refreshToken` 是否为空或错误
3. 修复命令：手动更新 homeAccountId

```bash
docker exec iMail node -e "
const db=require('better-sqlite3')('/app/data/imall.db');
const fs=require('fs');
