for(const acc of accs){
  const p='/app/data/msal_'+acc.email+'.json';
  if(!fs.existsSync(p)) continue;
  const cache=JSON.parse(fs.readFileSync(p,'utf8'));
  const match=Object.values(cache.Account||{}).find(a=>a.username?.toLowerCase()===acc.email.toLowerCase());
  if(match) db.prepare('UPDATE accounts SET config=? WHERE id=?').run(JSON.stringify({refreshToken:match.home_account_id}),acc.id);
  console.log(acc.email, match?.home_account_id||'not found');
}
"
